/* Données générées : Coran (texte othmanien, trad. Hamidullah) et hadiths (texte arabe de sunnah.com). */
window.QD = {"themes":{"ilm":"Le savoir d'Allah","kitaba":"L'écriture","mashia":"La volonté","khalq":"La création","choix":"Libre arbitre","effort":"Effort & causes","tawakkul":"Confiance en Allah","dua":"Invocation","sabr":"Patience & épreuves","shukr":"Gratitude","tawba":"Repentir","hidaya":"Guidée","justice":"Justice d'Allah","excuse":"L'excuse du destin","hikma":"Sagesse cachée","vie":"Vie, mort & subsistance","ghayb":"L'invisible"},"items":[{"id":"q54-49","type":"coran","ref":"54:49","src":"Coran 54:49 · Al-Qamar","title":"Toute chose créée avec mesure","verses":[{"n":49,"ar":"إِنَّا كُلَّ شَيۡءٍ خَلَقۡنَٰهُ بِقَدَرٖ","fr":"Nous avons créé toute chose avec mesure"}],"themes":["khalq","kitaba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/54/49"},{"id":"q25-2","type":"coran","ref":"25:2","src":"Coran 25:2 · Al-Furqan","title":"Il a tout créé, puis tout mesuré","verses":[{"n":2,"ar":"ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَخَلَقَ كُلَّ شَيۡءٖ فَقَدَّرَهُۥ تَقۡدِيرٗا","fr":"Celui à qui appartient la royauté des cieux et de la terre, qui ne S'est point attribué d'enfant, qui n'a point d'associé en Sa royauté et qui a créé toute chose en lui donnant ses justes proportions"}],"themes":["khalq"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/25/2"},{"id":"q22-70","type":"coran","ref":"22:70","src":"Coran 22:70 · Al-Hajj","title":"Tout cela est dans un Livre","verses":[{"n":70,"ar":"أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِنَّ ذَٰلِكَ فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ","fr":"Ne sais-tu pas qu'Allah sait ce qu'il y a dans le ciel et sur la terre? Tout cela est dans un Livre, et cela est pour Allah bien facile"}],"themes":["ilm","kitaba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/22/70"},{"id":"q6-59","type":"coran","ref":"6:59","src":"Coran 6:59 · Al-An'am","title":"Pas une feuille ne tombe sans qu'Il le sache","verses":[{"n":59,"ar":"۞وَعِندَهُۥ مَفَاتِحُ ٱلۡغَيۡبِ لَا يَعۡلَمُهَآ إِلَّا هُوَۚ وَيَعۡلَمُ مَا فِي ٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا يَعۡلَمُهَا وَلَا حَبَّةٖ فِي ظُلُمَٰتِ ٱلۡأَرۡضِ وَلَا رَطۡبٖ وَلَا يَابِسٍ إِلَّا فِي كِتَٰبٖ مُّبِينٖ","fr":"C'est Lui qui détient les clefs de l'Inconnaissable. Nul autre que Lui ne les connaît. Et Il connaît ce qui est dans la terre ferme, comme dans la mer. Et pas une feuille ne tombe qu'Il ne le sache. Et pas une graine dans les ténèbres de la terre, rien de frais ou de sec, qui ne soit consigné dans un livre explicite"}],"themes":["ilm","kitaba","ghayb"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/6/59"},{"id":"q6-28","type":"coran","ref":"6:28","src":"Coran 6:28 · Al-An'am","title":"Il sait même ce qui aurait été","verses":[{"n":28,"ar":"بَلۡ بَدَا لَهُم مَّا كَانُواْ يُخۡفُونَ مِن قَبۡلُۖ وَلَوۡ رُدُّواْ لَعَادُواْ لِمَا نُهُواْ عَنۡهُ وَإِنَّهُمۡ لَكَٰذِبُونَ","fr":"Mais non! Voilà que leur apparaîtra ce qu'auparavant ils cachaient. Or, s'ils étaient rendus [à la vie terrestre], ils reviendraient sûrement à ce qui leur était interdit. Ce sont vraiment des menteurs"}],"themes":["ilm"],"note":"Allah sait ce qui a été, ce qui sera, et ce qui aurait été si cela avait été : ici, ce que feraient les mécréants s'ils étaient renvoyés sur terre.","grade":"Coran","level":"coran","link":"https://quran.com/6/28"},{"id":"q2-255","type":"coran","ref":"2:255","src":"Coran 2:255 · Al-Baqarah","title":"Il connaît leur passé et leur futur","verses":[{"n":255,"ar":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ","fr":"Allah! Point de divinité à part Lui, le Vivant, Celui qui subsiste par lui-même «Al-Qayyûm». Ni somnolence ni sommeil ne Le saisissent. A Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission? Il connaît leur passé et leur futur. Et, de Sa science, ils n'embrassent que ce qu'Il veut. Son Trône «Kursiy», déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très Haut, le Très Grand"}],"themes":["ilm"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/255"},{"id":"q57-22-23","type":"coran","ref":"57:22-23","src":"Coran 57:22-23 · Al-Hadid","title":"Écrit avant d'être créé","verses":[{"n":22,"ar":"مَآ أَصَابَ مِن مُّصِيبَةٖ فِي ٱلۡأَرۡضِ وَلَا فِيٓ أَنفُسِكُمۡ إِلَّا فِي كِتَٰبٖ مِّن قَبۡلِ أَن نَّبۡرَأَهَآۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ","fr":"Nul malheur n'atteint la terre ni vos personnes, qui ne soit enregistré dans un Livre avant que Nous ne l'ayons créé; et cela est certes facile à Allah"},{"n":23,"ar":"لِّكَيۡلَا تَأۡسَوۡاْ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٍ","fr":"afin que vous ne vous tourmentiez pas au sujet de ce qui vous a échappé, ni n'exultiez pour ce qu'Il vous a donné. Et Allah n'aime point tout présomptueux plein de gloriole"}],"themes":["kitaba","sabr"],"note":"Le verset donne lui-même la raison de cette connaissance : ne pas te ronger pour ce qui t'a échappé, ne pas t'enorgueillir de ce que tu as reçu.","grade":"Coran","level":"coran","link":"https://quran.com/57/22-23"},{"id":"q9-51","type":"coran","ref":"9:51","src":"Coran 9:51 · At-Tawbah","title":"Rien ne nous atteint hormis ce qu'Allah a écrit","verses":[{"n":51,"ar":"قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوۡلَىٰنَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ","fr":"Dis: «Rien ne nous atteindra, en dehors de ce qu'Allah a prescrit pour nous. Il est notre Protecteur. C'est en Allah que les croyants doivent mettre leur confiance»"}],"themes":["kitaba","tawakkul"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/9/51"},{"id":"q11-6","type":"coran","ref":"11:6","src":"Coran 11:6 · Hud","title":"La subsistance de chaque être incombe à Allah","verses":[{"n":6,"ar":"۞وَمَا مِن دَآبَّةٖ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلّٞ فِي كِتَٰبٖ مُّبِينٖ","fr":"Il n'y a point de bête sur terre dont la subsistance n'incombe à Allah qui connaît son gîte et son dépôt; tout est dans un Livre explicite"}],"themes":["vie","kitaba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/11/6"},{"id":"q35-11","type":"coran","ref":"35:11","src":"Coran 35:11 · Fatir","title":"Aucune vie n'est prolongée ou abrégée sans être consignée","verses":[{"n":11,"ar":"وَٱللَّهُ خَلَقَكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ جَعَلَكُمۡ أَزۡوَٰجٗاۚ وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَمَا يُعَمَّرُ مِن مُّعَمَّرٖ وَلَا يُنقَصُ مِنۡ عُمُرِهِۦٓ إِلَّا فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ","fr":"Et Allah vous a créés de terre, puis d'une goutte de sperme, Il vous a ensuite établis en couples. Nulle femelle ne porte ni ne met bas sans qu'Il le sache. Et aucune existence n'est prolongée ou abrégée sans que cela soit consigné dans un livre. Cela est vraiment facile pour Allah"}],"themes":["vie","kitaba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/35/11"},{"id":"q36-12","type":"coran","ref":"36:12","src":"Coran 36:12 · Ya-Sin","title":"Nous écrivons ce qu’ils ont fait et leurs traces","verses":[{"n":12,"ar":"إِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمۡۚ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ فِيٓ إِمَامٖ مُّبِينٖ","fr":"C'est Nous qui ressuscitons les morts et écrivons ce qu'ils ont fait [pour l'au-delà] ainsi que leurs traces. Et Nous avons dénombré toute chose dans un registre explicite"}],"themes":["kitaba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/36/12"},{"id":"q17-13-14","type":"coran","ref":"17:13-14","src":"Coran 17:13-14 · Al-Isra","title":"Lis ton livre","verses":[{"n":13,"ar":"وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَـٰٓئِرَهُۥ فِي عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ كِتَٰبٗا يَلۡقَىٰهُ مَنشُورًا","fr":"Et au cou de chaque homme, Nous avons attaché son œuvre. Et au Jour de la Résurrection, Nous lui sortirons un écrit qu'il trouvera déroulé"},{"n":14,"ar":"ٱقۡرَأۡ كِتَٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡيَوۡمَ عَلَيۡكَ حَسِيبٗا","fr":"«Lis ton écrit. Aujourd'hui, tu te suffis d'être ton propre comptable»"}],"themes":["kitaba","choix"],"note":"Le livre de tes actes, ce sont tes propres choix qui l'écrivent : tu le liras toi-même au Jour dernier.","grade":"Coran","level":"coran","link":"https://quran.com/17/13-14"},{"id":"q50-17-18","type":"coran","ref":"50:17-18","src":"Coran 50:17-18 · Qaf","title":"Deux anges qui consignent","verses":[{"n":17,"ar":"إِذۡ يَتَلَقَّى ٱلۡمُتَلَقِّيَانِ عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٞ","fr":"quand les deux recueillants, assis à droite et à gauche, recueillent"},{"n":18,"ar":"مَّا يَلۡفِظُ مِن قَوۡلٍ إِلَّا لَدَيۡهِ رَقِيبٌ عَتِيدٞ","fr":"Il ne prononce pas une parole sans avoir auprès de lui un observateur prêt à l'inscrire"}],"themes":["kitaba","choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/50/17-18"},{"id":"q45-29","type":"coran","ref":"45:29","src":"Coran 45:29 · Al-Jathiyah","title":"Nous enregistrions ce que vous faisiez","verses":[{"n":29,"ar":"هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيۡكُم بِٱلۡحَقِّۚ إِنَّا كُنَّا نَسۡتَنسِخُ مَا كُنتُمۡ تَعۡمَلُونَ","fr":"Voilà Notre Livre. Il parle de vous en toute vérité car Nous enregistrions [tout] ce que vous faisiez»"}],"themes":["kitaba","choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/45/29"},{"id":"q7-172","type":"coran","ref":"7:172","src":"Coran 7:172 · Al-A'raf","title":"Le pacte des descendants d'Adam","verses":[{"n":172,"ar":"وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ وَأَشۡهَدَهُمۡ عَلَىٰٓ أَنفُسِهِمۡ أَلَسۡتُ بِرَبِّكُمۡۖ قَالُواْ بَلَىٰ شَهِدۡنَآۚ أَن تَقُولُواْ يَوۡمَ ٱلۡقِيَٰمَةِ إِنَّا كُنَّا عَنۡ هَٰذَا غَٰفِلِينَ","fr":"Et quand ton Seigneur tira une descendance des reins des fils d'Adam et les fit témoigner sur eux-mêmes: «Ne suis-Je pas votre Seigneur?» Ils répondirent: «Mais si, nous en témoignons...» - afin que vous ne disiez point, au Jour de la Résurrection: «Vraiment, nous n'y avons pas fait attention»"}],"themes":["kitaba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/7/172"},{"id":"q44-3-4","type":"coran","ref":"44:3-4","src":"Coran 44:3-4 · Ad-Dukhan","title":"La nuit où tout ordre sage est décidé","verses":[{"n":3,"ar":"إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةٖ مُّبَٰرَكَةٍۚ إِنَّا كُنَّا مُنذِرِينَ","fr":"Nous l'avons fait descendre en une nuit bénie, Nous sommes en vérité Celui qui avertit"},{"n":4,"ar":"فِيهَا يُفۡرَقُ كُلُّ أَمۡرٍ حَكِيمٍ","fr":"durant laquelle est décidé tout ordre sage"}],"themes":["kitaba"],"note":"Les savants y voient le décret annuel, détaillé chaque année lors de Laylat al-Qadr.","grade":"Coran","level":"coran","link":"https://quran.com/44/3-4"},{"id":"q97-4","type":"coran","ref":"97:4","src":"Coran 97:4 · Al-Qadr","title":"Les anges descendent pour chaque ordre","verses":[{"n":4,"ar":"تَنَزَّلُ ٱلۡمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرٖ","fr":"Durant celle-ci descendent les Anges ainsi que l'Esprit, par permission de leur Seigneur pour tout ordre"}],"themes":["kitaba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/97/4"},{"id":"q55-29","type":"coran","ref":"55:29","src":"Coran 55:29 · Ar-Rahman","title":"Chaque jour, Il est à une œuvre","verses":[{"n":29,"ar":"يَسۡـَٔلُهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ كُلَّ يَوۡمٍ هُوَ فِي شَأۡنٖ","fr":"Ceux qui sont dans les cieux et la terre L'implorent. Chaque jour, Il accomplit une œuvre nouvelle"}],"themes":["kitaba","mashia"],"note":"Les savants y voient le décret quotidien : Il donne la vie et la mort, élève et abaisse, exauce et accorde.","grade":"Coran","level":"coran","link":"https://quran.com/55/29"},{"id":"q13-39","type":"coran","ref":"13:39","src":"Coran 13:39 · Ar-Ra'd","title":"Il efface et Il confirme ; l'Écriture mère est auprès de Lui","verses":[{"n":39,"ar":"يَمۡحُواْ ٱللَّهُ مَا يَشَآءُ وَيُثۡبِتُۖ وَعِندَهُۥٓ أُمُّ ٱلۡكِتَٰبِ","fr":"Allah efface ou confirme ce qu'Il veut et l'Ecriture primordiale est auprès de Lui"}],"themes":["kitaba","dua"],"note":"Ce que portent les registres des anges peut être effacé ou confirmé (par exemple sous l'effet de l'invocation ou des liens de parenté) ; la Mère du Livre, elle, ne change pas.","grade":"Coran","level":"coran","link":"https://quran.com/13/39"},{"id":"q33-38","type":"coran","ref":"33:38","src":"Coran 33:38 · Al-Ahzab","title":"L'ordre d'Allah est un décret inéluctable","verses":[{"n":38,"ar":"مَّا كَانَ عَلَى ٱلنَّبِيِّ مِنۡ حَرَجٖ فِيمَا فَرَضَ ٱللَّهُ لَهُۥۖ سُنَّةَ ٱللَّهِ فِي ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلُۚ وَكَانَ أَمۡرُ ٱللَّهِ قَدَرٗا مَّقۡدُورًا","fr":"Nul grief à faire au Prophète en ce qu'Allah lui a imposé, conformément aux lois établies pour ceux qui vécurent antérieurement. Le commandement d'Allah est un décret inéluctable"}],"themes":["kitaba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/33/38"},{"id":"q81-28-29","type":"coran","ref":"81:28-29","src":"Coran 81:28-29 · At-Takwir","title":"Ta volonté, sous Sa volonté","verses":[{"n":28,"ar":"لِمَن شَآءَ مِنكُمۡ أَن يَسۡتَقِيمَ","fr":"pour celui d'entre vous qui veut suivre le chemin droit"},{"n":29,"ar":"وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ","fr":"Mais vous ne pouvez vouloir, que si Allah veut, [Lui], le Seigneur de l'Univers"}],"themes":["mashia","choix"],"note":"Les deux versets se tiennent : une volonté réelle t'est reconnue (28), et elle ne sort jamais de la volonté d'Allah (29).","grade":"Coran","level":"coran","link":"https://quran.com/81/28-29"},{"id":"q76-29-30","type":"coran","ref":"76:29-30","src":"Coran 76:29-30 · Al-Insan","title":"Que celui qui veut prenne le chemin","verses":[{"n":29,"ar":"إِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا","fr":"Ceci est un rappel. Que celui qui veut prenne donc le chemin vers son Seigneur"},{"n":30,"ar":"وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا","fr":"Cependant, vous ne saurez vouloir, à moins qu'Allah veuille. Et Allah est Omniscient et Sage"}],"themes":["mashia","choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/76/29-30"},{"id":"q74-54-56","type":"coran","ref":"74:54-56","src":"Coran 74:54-56 · Al-Muddaththir","title":"Quiconque veut, qu’il se rappelle","verses":[{"n":54,"ar":"كَلَّآ إِنَّهُۥ تَذۡكِرَةٞ","fr":"Ah! Non! Ceci est vraiment un Rappel"},{"n":55,"ar":"فَمَن شَآءَ ذَكَرَهُۥ","fr":"Quiconque veut, qu'il se le rappelle"},{"n":56,"ar":"وَمَا يَذۡكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ هُوَ أَهۡلُ ٱلتَّقۡوَىٰ وَأَهۡلُ ٱلۡمَغۡفِرَةِ","fr":"Mais ils ne se rappelleront que si Allah veut. C'est Lui qui est Le plus digne d'être craint; et c'est Lui qui détient le pardon"}],"themes":["mashia","choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/74/54-56"},{"id":"q36-82","type":"coran","ref":"36:82","src":"Coran 36:82 · Ya-Sin","title":"« Sois », et c’est","verses":[{"n":82,"ar":"إِنَّمَآ أَمۡرُهُۥٓ إِذَآ أَرَادَ شَيۡـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ","fr":"Quand Il veut une chose, Son commandement consiste à dire: «Sois», et c'est"}],"themes":["mashia","khalq"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/36/82"},{"id":"q2-253","type":"coran","ref":"2:253","src":"Coran 2:253 · Al-Baqarah","title":"Allah fait ce qu’Il veut","verses":[{"n":253,"ar":"۞تِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ وَرَفَعَ بَعۡضَهُمۡ دَرَجَٰتٖۚ وَءَاتَيۡنَا عِيسَى ٱبۡنَ مَرۡيَمَ ٱلۡبَيِّنَٰتِ وَأَيَّدۡنَٰهُ بِرُوحِ ٱلۡقُدُسِۗ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِينَ مِنۢ بَعۡدِهِم مِّنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ وَلَٰكِنِ ٱخۡتَلَفُواْ فَمِنۡهُم مَّنۡ ءَامَنَ وَمِنۡهُم مَّن كَفَرَۚ وَلَوۡ شَآءَ ٱللَّهُ مَا ٱقۡتَتَلُواْ وَلَٰكِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ","fr":"Parmi ces messagers, Nous avons favorisé certains par rapport à d'autres. Il en est à qui Allah a parlé; et Il en a élevé d'autres en grade. A Jésus fils de Marie Nous avons apporté les preuves, et l'avons fortifié par le Saint-Esprit. Et si Allah avait voulu, les gens qui vinrent après eux ne se seraient pas entretués, après que les preuves leur furent venues; mais ils se sont opposés: les uns restèrent croyants, les autres furent infidèles. Si Allah avait voulu, ils ne se seraient pas entretués; mais Allah fait ce qu'Il veut"}],"themes":["mashia"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/253"},{"id":"q85-16","type":"coran","ref":"85:16","src":"Coran 85:16 · Al-Buruj","title":"Il réalise tout ce qu’Il veut","verses":[{"n":16,"ar":"فَعَّالٞ لِّمَا يُرِيدُ","fr":"Il réalise parfaitement tout ce qu'Il veut"}],"themes":["mashia"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/85/16"},{"id":"q28-68","type":"coran","ref":"28:68","src":"Coran 28:68 · Al-Qasas","title":"Ton Seigneur crée ce qu’Il veut et Il choisit","verses":[{"n":68,"ar":"وَرَبُّكَ يَخۡلُقُ مَا يَشَآءُ وَيَخۡتَارُۗ مَا كَانَ لَهُمُ ٱلۡخِيَرَةُۚ سُبۡحَٰنَ ٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ","fr":"Ton Seigneur crée ce qu'Il veut et Il choisit; il ne leur a jamais appartenu de choisir. Gloire à Allah! Il transcende ce qu'ils associent à Lui"}],"themes":["mashia"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/28/68"},{"id":"q10-99","type":"coran","ref":"10:99","src":"Coran 10:99 · Yunus","title":"Est-ce à toi de contraindre les gens ?","verses":[{"n":99,"ar":"وَلَوۡ شَآءَ رَبُّكَ لَأٓمَنَ مَن فِي ٱلۡأَرۡضِ كُلُّهُمۡ جَمِيعًاۚ أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُواْ مُؤۡمِنِينَ","fr":"Si ton Seigneur l'avait voulu, tous ceux qui sont sur la terre auraient cru. Est-ce à toi de contraindre les gens à devenir croyants"}],"themes":["mashia","choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/10/99"},{"id":"q16-93","type":"coran","ref":"16:93","src":"Coran 16:93 · An-Nahl","title":"Et vous serez interrogés sur ce que vous faisiez","verses":[{"n":93,"ar":"وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَلَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَعۡمَلُونَ","fr":"Si Allah avait voulu, Il aurait certes fait de vous une seule communauté. Mais Il laisse s'égarer qui Il veut et guide qui Il veut. Et vous serez certes, interrogés sur ce que vous faisiez"}],"themes":["mashia","choix"],"note":"Dans un même verset : la volonté souveraine d'Allah et ta pleine responsabilité.","grade":"Coran","level":"coran","link":"https://quran.com/16/93"},{"id":"q6-125","type":"coran","ref":"6:125","src":"Coran 6:125 · Al-An'am","title":"Il ouvre la poitrine de celui qu’Il veut guider","verses":[{"n":125,"ar":"فَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ وَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ كَذَٰلِكَ يَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِينَ لَا يُؤۡمِنُونَ","fr":"Et puis, quiconque Allah veut guider, Il lui ouvre la poitrine à l'Islam. Et quiconque Il veut égarer, Il rend sa poitrine étroite et gênée, comme s'il s'efforçait de monter au ciel. Ainsi Allah inflige Sa punition à ceux qui ne croient pas"}],"themes":["mashia","hidaya"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/6/125"},{"id":"q39-7","type":"coran","ref":"39:7","src":"Coran 39:7 · Az-Zumar","title":"Il n'agrée pas la mécréance de Ses serviteurs","verses":[{"n":7,"ar":"إِن تَكۡفُرُواْ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنكُمۡۖ وَلَا يَرۡضَىٰ لِعِبَادِهِ ٱلۡكُفۡرَۖ وَإِن تَشۡكُرُواْ يَرۡضَهُ لَكُمۡۗ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ","fr":"Si vous ne croyez pas, Allah se passe largement de vous. De Ses serviteurs cependant, Il n'agrée pas la mécréance. Et si vous êtes reconnaissants, Il l'agrée pour vous. Nul pécheur ne portera les péchés d'autrui. Ensuite, vers votre Seigneur sera votre retour: Il vous informera alors de ce que vous faisiez car Il connaît parfaitement le contenu des poitrines"}],"themes":["mashia"],"note":"Allah peut laisser arriver une chose (volonté cosmique) qu'Il n'aime pas (volonté religieuse).","grade":"Coran","level":"coran","link":"https://quran.com/39/7"},{"id":"q2-185","type":"coran","ref":"2:185","src":"Coran 2:185 · Al-Baqarah","title":"Allah veut pour vous la facilité","verses":[{"n":185,"ar":"شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ","fr":"(Ces jours sont) le mois de Ramadân au cours duquel le Coran a été descendu comme guide pour les gens, et preuves claires de la bonne direction et du discernement. Donc, quiconque d'entre vous est présent en ce mois, qu'il jeûne! Et quiconque est malade ou en voyage, alors qu'il jeûne un nombre égal d'autres jours. - Allah veut pour vous la facilité, Il ne veut pas la difficulté pour vous, afin que vous en complétiez le nombre et que vous proclamiez la grandeur d'Allah pour vous avoir guidés, et afin que vous soyez reconnaissants"}],"themes":["mashia"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/185"},{"id":"q33-36","type":"coran","ref":"33:36","src":"Coran 33:36 · Al-Ahzab","title":"Quand Allah et Son messager ont décidé…","verses":[{"n":36,"ar":"وَمَا كَانَ لِمُؤۡمِنٖ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمۡرًا أَن يَكُونَ لَهُمُ ٱلۡخِيَرَةُ مِنۡ أَمۡرِهِمۡۗ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ ضَلَّ ضَلَٰلٗا مُّبِينٗا","fr":"Il n'appartient pas à un croyant ou à une croyante, une fois qu'Allah et Son messager ont décidé d'une chose d'avoir encore le choix dans leur façon d'agir. Et quiconque désobéit à Allah et à Son messager, s'est égaré certes, d'un égarement évident"}],"themes":["mashia"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/33/36"},{"id":"q6-17","type":"coran","ref":"6:17","src":"Coran 6:17 · Al-An'am","title":"Nul autre que Lui ne peut enlever un mal","verses":[{"n":17,"ar":"وَإِن يَمۡسَسۡكَ ٱللَّهُ بِضُرّٖ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَۖ وَإِن يَمۡسَسۡكَ بِخَيۡرٖ فَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","fr":"Et si Allah fait qu'un malheur te touche, nul autre que Lui ne peut l'enlever. Et s'Il fait qu'un bonheur te touche... c'est qu'Il est Omnipotent"}],"themes":["mashia"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/6/17"},{"id":"q35-2","type":"coran","ref":"35:2","src":"Coran 35:2 · Fatir","title":"Ce qu’Allah ouvre, nul ne le retient","verses":[{"n":2,"ar":"مَّا يَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةٖ فَلَا مُمۡسِكَ لَهَاۖ وَمَا يُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","fr":"Ce qu'Allah accorde en miséricorde aux gens, il n'est personne à pouvoir le retenir. Et ce qu'Il retient, il n'est personne à le relâcher après Lui. Et c'est Lui le Puissant, le Sage"}],"themes":["mashia"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/35/2"},{"id":"q18-23-24","type":"coran","ref":"18:23-24","src":"Coran 18:23-24 · Al-Kahf","title":"« Si Allah le veut »","verses":[{"n":23,"ar":"وَلَا تَقُولَنَّ لِشَاْيۡءٍ إِنِّي فَاعِلٞ ذَٰلِكَ غَدًا","fr":"Et ne dis jamais, à propos d'une chose: «Je la ferai sûrement demain»"},{"n":24,"ar":"إِلَّآ أَن يَشَآءَ ٱللَّهُۚ وَٱذۡكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلۡ عَسَىٰٓ أَن يَهۡدِيَنِ رَبِّي لِأَقۡرَبَ مِنۡ هَٰذَا رَشَدٗا","fr":"sans ajouter: «Si Allah le veut», et invoque ton Seigneur quand tu oublies et dis: «Je souhaite que mon Seigneur me guide et me mène plus près de ce qui est correct»"}],"themes":["mashia"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/18/23-24"},{"id":"q21-23","type":"coran","ref":"21:23","src":"Coran 21:23 · Al-Anbya","title":"Il n'est pas interrogé sur ce qu'Il fait","verses":[{"n":23,"ar":"لَا يُسۡـَٔلُ عَمَّا يَفۡعَلُ وَهُمۡ يُسۡـَٔلُونَ","fr":"Il n'est pas interrogé sur ce qu'Il fait, mais ce sont eux qui devront rendre compte [de leurs actes]"}],"themes":["mashia","hikma"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/21/23"},{"id":"q12-21","type":"coran","ref":"12:21","src":"Coran 12:21 · Yusuf","title":"Allah est souverain en Son commandement","verses":[{"n":21,"ar":"وَقَالَ ٱلَّذِي ٱشۡتَرَىٰهُ مِن مِّصۡرَ لِٱمۡرَأَتِهِۦٓ أَكۡرِمِي مَثۡوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗاۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ وَلِنُعَلِّمَهُۥ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمۡرِهِۦ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ","fr":"Et celui qui l'acheta était de l'Egypte. Il dit à sa femme: «Accorde lui une généreuse hospitalité. Il se peut qu'il nous soit utile ou que nous l'adoptions comme notre enfant.» Ainsi avons-nous raffermi Joseph dans le pays et nous lui avons appris l'interprétation des rêves. Et Allah est souverain en Son Commandement: mais la plupart des gens ne savent pas"}],"themes":["mashia","hikma"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/12/21"},{"id":"q42-49-50","type":"coran","ref":"42:49-50","src":"Coran 42:49-50 · Ash-Shuraa","title":"Il donne des filles, des garçons, ou la stérilité","verses":[{"n":49,"ar":"لِّلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَخۡلُقُ مَا يَشَآءُۚ يَهَبُ لِمَن يَشَآءُ إِنَٰثٗا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ","fr":"A Allah appartient la royauté des cieux et de la terre. Il crée ce qu'Il veut. Il fait don de filles à qui Il veut, et don de garçons à qui Il veut"},{"n":50,"ar":"أَوۡ يُزَوِّجُهُمۡ ذُكۡرَانٗا وَإِنَٰثٗاۖ وَيَجۡعَلُ مَن يَشَآءُ عَقِيمًاۚ إِنَّهُۥ عَلِيمٞ قَدِيرٞ","fr":"ou bien Il donne à la fois garçons et filles; et Il rend stérile qui Il veut. Il est certes Omniscient et Omnipotent"}],"themes":["mashia","vie"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/42/49-50"},{"id":"q37-96","type":"coran","ref":"37:96","src":"Coran 37:96 · As-Saffat","title":"Allah vous a créés, vous et ce que vous faites","verses":[{"n":96,"ar":"وَٱللَّهُ خَلَقَكُمۡ وَمَا تَعۡمَلُونَ","fr":"alors que c'est Allah qui vous a créés, vous et ce que vous fabriquez?»"}],"themes":["khalq"],"note":"Hamidullah traduit « ce que vous fabriquez » (les idoles). Les savants, dont al-Bukhârî, y lisent aussi : Allah a créé vos actes.","grade":"Coran","level":"coran","link":"https://quran.com/37/96"},{"id":"q8-17","type":"coran","ref":"8:17","src":"Coran 8:17 · Al-Anfal","title":"Ce n'est pas toi qui lançais","verses":[{"n":17,"ar":"فَلَمۡ تَقۡتُلُوهُمۡ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمۡۚ وَمَا رَمَيۡتَ إِذۡ رَمَيۡتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ وَلِيُبۡلِيَ ٱلۡمُؤۡمِنِينَ مِنۡهُ بَلَآءً حَسَنًاۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ","fr":"Ce n'est pas vous qui les avez tués: mais c'est Allah qui les a tués. Et lorsque tu lançais (une poignée de terre), ce n'est pas toi qui lançais: mais c'est Allah qui lançait, et ce pour éprouver les croyants d'une belle épreuve de Sa part! Allah est Audient et Omniscient"}],"themes":["khalq"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/8/17"},{"id":"q3-6","type":"coran","ref":"3:6","src":"Coran 3:6 · Ali 'Imran","title":"Il vous façonne dans les matrices comme Il veut","verses":[{"n":6,"ar":"هُوَ ٱلَّذِي يُصَوِّرُكُمۡ فِي ٱلۡأَرۡحَامِ كَيۡفَ يَشَآءُۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","fr":"C'est Lui qui vous donne forme dans les matrices comme Il veut. Point de divinité à part Lui, le Puissant, le Sage"}],"themes":["khalq"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/3/6"},{"id":"q80-18-20","type":"coran","ref":"80:18-20","src":"Coran 80:18-20 · 'Abasa","title":"Il le crée, le mesure, puis lui facilite le chemin","verses":[{"n":18,"ar":"مِنۡ أَيِّ شَيۡءٍ خَلَقَهُۥ","fr":"De quoi [Allah] l'a-t-Il créé"},{"n":19,"ar":"مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ","fr":"D'une goutte de sperme, Il le crée et détermine (son destin)"},{"n":20,"ar":"ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ","fr":"puis Il lui facilite le chemin"}],"themes":["khalq","hidaya"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/80/18-20"},{"id":"q87-2-3","type":"coran","ref":"87:2-3","src":"Coran 87:2-3 · Al-A'la","title":"Il a décrété et guidé","verses":[{"n":2,"ar":"ٱلَّذِي خَلَقَ فَسَوَّىٰ","fr":"Celui Qui a créé et agencé harmonieusement"},{"n":3,"ar":"وَٱلَّذِي قَدَّرَ فَهَدَىٰ","fr":"qui a décrété et guidé"}],"themes":["khalq","hidaya"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/87/2-3"},{"id":"q15-21","type":"coran","ref":"15:21","src":"Coran 15:21 · Al-Hijr","title":"Rien ne descend que dans une mesure connue","verses":[{"n":21,"ar":"وَإِن مِّن شَيۡءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٖ مَّعۡلُومٖ","fr":"Et il n'est rien dont Nous n'ayons les réserves et Nous ne le faisons descendre que dans une mesure déterminée"}],"themes":["khalq","vie"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/15/21"},{"id":"q2-286","type":"coran","ref":"2:286","src":"Coran 2:286 · Al-Baqarah","title":"Pas de charge au-delà de la capacité","verses":[{"n":286,"ar":"لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","fr":"Allah n'impose à aucune âme une charge supérieure à sa capacité. Elle sera récompensée du bien qu'elle aura fait, punie du mal qu'elle aura fait. Seigneur, ne nous châtie pas s'il nous arrive d'oublier ou de commettre une erreur. Seigneur! Ne nous charge pas d'un fardeau lourd comme Tu as chargé ceux qui vécurent avant nous. Seigneur! Ne nous impose pas ce que nous ne pouvons supporter, efface nos fautes, pardonne-nous et fais nous miséricorde. Tu es Notre Maître, accorde-nous donc la victoire sur les peuples infidèles"}],"themes":["choix","justice"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/286"},{"id":"q76-3","type":"coran","ref":"76:3","src":"Coran 76:3 · Al-Insan","title":"Reconnaissant ou ingrat","verses":[{"n":3,"ar":"إِنَّا هَدَيۡنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرٗا وَإِمَّا كَفُورًا","fr":"Nous l'avons guidé dans le chemin, - qu'il soit reconnaissant ou ingrat"}],"themes":["choix","hidaya"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/76/3"},{"id":"q90-10","type":"coran","ref":"90:10","src":"Coran 90:10 · Al-Balad","title":"Guidé aux deux voies","verses":[{"n":10,"ar":"وَهَدَيۡنَٰهُ ٱلنَّجۡدَيۡنِ","fr":"Ne l'avons-Nous pas guidé aux deux voies"}],"themes":["choix","hidaya"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/90/10"},{"id":"q91-7-10","type":"coran","ref":"91:7-10","src":"Coran 91:7-10 · Ash-Shams","title":"A réussi celui qui purifie son âme","verses":[{"n":7,"ar":"وَنَفۡسٖ وَمَا سَوَّىٰهَا","fr":"Et par l'âme et Celui qui l'a harmonieusement façonnée"},{"n":8,"ar":"فَأَلۡهَمَهَا فُجُورَهَا وَتَقۡوَىٰهَا","fr":"et lui a alors inspiré son immoralité, de même que sa piété"},{"n":9,"ar":"قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا","fr":"A réussi, certes, celui qui la purifie"},{"n":10,"ar":"وَقَدۡ خَابَ مَن دَسَّىٰهَا","fr":"Et est perdu, certes, celui qui la corrompt"}],"themes":["choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/91/7-10"},{"id":"q18-29","type":"coran","ref":"18:29","src":"Coran 18:29 · Al-Kahf","title":"Quiconque le veut, qu’il croie","verses":[{"n":29,"ar":"وَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَآءَ فَلۡيُؤۡمِن وَمَن شَآءَ فَلۡيَكۡفُرۡۚ إِنَّآ أَعۡتَدۡنَا لِلظَّـٰلِمِينَ نَارًا أَحَاطَ بِهِمۡ سُرَادِقُهَاۚ وَإِن يَسۡتَغِيثُواْ يُغَاثُواْ بِمَآءٖ كَٱلۡمُهۡلِ يَشۡوِي ٱلۡوُجُوهَۚ بِئۡسَ ٱلشَّرَابُ وَسَآءَتۡ مُرۡتَفَقًا","fr":"Et dis: «La vérité émane de votre Seigneur». Quiconque le veut, qu'il croie, quiconque le veut qu'il mécroie». Nous avons préparé pour les injustes un Feu dont les flammes les cernent. Et s'ils implorent à boire on les abreuvera d'une eau comme du métal fondu brûlant les visages. Quelle mauvaise boisson et quelle détestable demeure"}],"themes":["choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/18/29"},{"id":"q2-256","type":"coran","ref":"2:256","src":"Coran 2:256 · Al-Baqarah","title":"Nulle contrainte en religion","verses":[{"n":256,"ar":"لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّـٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","fr":"Nulle contrainte en religion! Car le bon chemin s'est distingué de l'égarement. Donc, quiconque mécroit au Rebelle tandis qu'il croit en Allah saisit l'anse la plus solide, qui ne peut se briser. Et Allah est Audient et Omniscient"}],"themes":["choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/256"},{"id":"q13-11","type":"coran","ref":"13:11","src":"Coran 13:11 · Ar-Ra'd","title":"Change ce qui est en toi","verses":[{"n":11,"ar":"لَهُۥ مُعَقِّبَٰتٞ مِّنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ يَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوۡمٖ سُوٓءٗا فَلَا مَرَدَّ لَهُۥۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ","fr":"Il [l'homme] a par devant lui et derrière lui des Anges qui se relaient et qui veillent sur lui par ordre d'Allah. En vérité, Allah ne modifie point l'état d'un peuple, tant que les [individus qui le composent] ne modifient pas ce qui est en eux-mêmes. Et lorsqu'Allah veut [infliger] un mal à un peuple, nul ne peut le repousser: ils n'ont en dehors de Lui aucun protecteur"}],"themes":["choix","effort"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/13/11"},{"id":"q8-53","type":"coran","ref":"8:53","src":"Coran 8:53 · Al-Anfal","title":"Allah ne retire pas un bienfait tant qu'on ne change pas","verses":[{"n":53,"ar":"ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمۡ يَكُ مُغَيِّرٗا نِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ","fr":"C'est qu'en effet Allah ne modifie pas un bienfait dont Il a gratifié un peuple avant que celui-ci change ce qui est en lui-même. Et Allah est, Audient et Omniscient"}],"themes":["choix","shukr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/8/53"},{"id":"q53-39-41","type":"coran","ref":"53:39-41","src":"Coran 53:39-41 · An-Najm","title":"L'homme n'obtient que le fruit de ses efforts","verses":[{"n":39,"ar":"وَأَن لَّيۡسَ لِلۡإِنسَٰنِ إِلَّا مَا سَعَىٰ","fr":"et qu'en vérité, l'homme n'obtient que [le fruit] de ses efforts"},{"n":40,"ar":"وَأَنَّ سَعۡيَهُۥ سَوۡفَ يُرَىٰ","fr":"et que son effort, en vérité, lui sera présenté (le jour du Jugement)"},{"n":41,"ar":"ثُمَّ يُجۡزَىٰهُ ٱلۡجَزَآءَ ٱلۡأَوۡفَىٰ","fr":"Ensuite il en sera récompensé pleinement"}],"themes":["effort","choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/53/39-41"},{"id":"q4-78-79","type":"coran","ref":"4:78-79","src":"Coran 4:78-79 · An-Nisa","title":"Tout vient d’Allah… et le mal qui t’atteint vient de toi","verses":[{"n":78,"ar":"أَيۡنَمَا تَكُونُواْ يُدۡرِككُّمُ ٱلۡمَوۡتُ وَلَوۡ كُنتُمۡ فِي بُرُوجٖ مُّشَيَّدَةٖۗ وَإِن تُصِبۡهُمۡ حَسَنَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِكَۚ قُلۡ كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَـٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ حَدِيثٗا","fr":"Où que vous soyez, la mort vous atteindra, fussiez-vous dans des tours imprenables. Qu'un bien les atteigne, ils disent: «C'est de la part d'Allah.» Qu'un mal les atteigne, ils disent: «C'est dû à toi (Muhammad).» Dis: «Tout est d'Allah.» Mais qu'ont-ils ces gens, à ne comprendre presque aucune parole"},{"n":79,"ar":"مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَۚ وَأَرۡسَلۡنَٰكَ لِلنَّاسِ رَسُولٗاۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا","fr":"Tout bien qui t'atteint vient d'Allah, et tout mal qui t'atteint vient de toi-même. Et nous t'avons envoyé aux gens comme Messager. Et Allah suffit comme témoin"}],"themes":["mashia","choix"],"note":"Tout est créé et décrété par Allah (78) ; mais le mal qui t'atteint a souvent pour cause tes propres actes (79).","grade":"Coran","level":"coran","link":"https://quran.com/4/78-79"},{"id":"q3-165-166","type":"coran","ref":"3:165-166","src":"Coran 3:165-166 · Ali 'Imran","title":"Uhud : « cela vient de vous-mêmes »… « par la permission d’Allah »","verses":[{"n":165,"ar":"أَوَلَمَّآ أَصَٰبَتۡكُم مُّصِيبَةٞ قَدۡ أَصَبۡتُم مِّثۡلَيۡهَا قُلۡتُمۡ أَنَّىٰ هَٰذَاۖ قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","fr":"Quoi! Quand un malheur vous atteint - mais vous en avez jadis infligé le double - vous dites: «D'où vient cela?» Réponds-leur: «Il vient de vous-mêmes». Certes Allah est Omnipotent"},{"n":166,"ar":"وَمَآ أَصَٰبَكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ فَبِإِذۡنِ ٱللَّهِ وَلِيَعۡلَمَ ٱلۡمُؤۡمِنِينَ","fr":"Et tout ce que vous avez subi, le jour où les deux troupes se rencontrèrent, c'est par permission d'Allah, et afin qu'Il distingue les croyants"}],"themes":["choix","mashia"],"note":"Deux lectures vraies du même événement : la cause humaine (165) et le décret divin (166).","grade":"Coran","level":"coran","link":"https://quran.com/3/165-166"},{"id":"q30-41","type":"coran","ref":"30:41","src":"Coran 30:41 · Ar-Rum","title":"La corruption, à cause de ce que les mains ont acquis","verses":[{"n":41,"ar":"ظَهَرَ ٱلۡفَسَادُ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ أَيۡدِي ٱلنَّاسِ لِيُذِيقَهُم بَعۡضَ ٱلَّذِي عَمِلُواْ لَعَلَّهُمۡ يَرۡجِعُونَ","fr":"La corruption est apparue sur la terre et dans la mer à cause de ce que les gens ont accompli de leurs propres mains; afin qu'[Allah] leur fasse goûter une partie de ce qu'ils ont œuvré; peut-être reviendront-ils (vers Allah)"}],"themes":["choix","sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/30/41"},{"id":"q42-30","type":"coran","ref":"42:30","src":"Coran 42:30 · Ash-Shuraa","title":"Tout malheur est dû à ce que vos mains ont acquis","verses":[{"n":30,"ar":"وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٖ فَبِمَا كَسَبَتۡ أَيۡدِيكُمۡ وَيَعۡفُواْ عَن كَثِيرٖ","fr":"Tout malheur qui vous atteint est dû à ce que vos mains ont acquis. Et Il pardonne beaucoup"}],"themes":["choix","sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/42/30"},{"id":"q7-96","type":"coran","ref":"7:96","src":"Coran 7:96 · Al-A'raf","title":"La foi et la piété ouvrent les bénédictions","verses":[{"n":96,"ar":"وَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰٓ ءَامَنُواْ وَٱتَّقَوۡاْ لَفَتَحۡنَا عَلَيۡهِم بَرَكَٰتٖ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ وَلَٰكِن كَذَّبُواْ فَأَخَذۡنَٰهُم بِمَا كَانُواْ يَكۡسِبُونَ","fr":"Si les habitants des cités avaient cru et avaient été pieux, Nous leur aurions certainement accordé des bénédictions du ciel et de la terre. Mais ils ont démenti et Nous les avons donc saisis, pour ce qu'ils avaient acquis"}],"themes":["choix","vie"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/7/96"},{"id":"q16-106","type":"coran","ref":"16:106","src":"Coran 16:106 · An-Nahl","title":"Sauf celui qui y a été contraint","verses":[{"n":106,"ar":"مَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِيمَٰنِهِۦٓ إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ صَدۡرٗا فَعَلَيۡهِمۡ غَضَبٞ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِيمٞ","fr":"Quiconque a renié Allah après avoir cru... - sauf celui qui y a été contraint alors que son cœur demeure plein de la sérénité de la foi - mais ceux qui ouvrent délibérément leur cœur à la mécréance, ceux-là ont sur eux une colère d'Allah et ils ont un châtiment terrible"}],"themes":["choix","justice"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/16/106"},{"id":"q33-5","type":"coran","ref":"33:5","src":"Coran 33:5 · Al-Ahzab","title":"Nul blâme pour l’erreur","verses":[{"n":5,"ar":"ٱدۡعُوهُمۡ لِأٓبَآئِهِمۡ هُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ فَإِن لَّمۡ تَعۡلَمُوٓاْ ءَابَآءَهُمۡ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِ وَمَوَٰلِيكُمۡۚ وَلَيۡسَ عَلَيۡكُمۡ جُنَاحٞ فِيمَآ أَخۡطَأۡتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا","fr":"Appelez-les du nom de leurs pères: c'est plus équitable devant Allah. Mais si vous ne connaissez pas leurs pères, alors considérez-les comme vos frères en religion ou vos alliés. Nul blâme sur vous pour ce que vous faites par erreur, mais (vous serez blâmés pour) ce que vos cœurs font délibérément. Allah, cependant, est Pardonneur et Miséricordieux"}],"themes":["choix","justice"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/33/5"},{"id":"q17-36","type":"coran","ref":"17:36","src":"Coran 17:36 · Al-Isra","title":"L'ouïe, la vue et le cœur seront interrogés","verses":[{"n":36,"ar":"وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَـٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولٗا","fr":"Et ne poursuis pas ce dont tu n'as aucune connaissance. L'ouïe, la vue et le cœur: sur tout cela, en vérité, on sera interrogé"}],"themes":["choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/17/36"},{"id":"q17-15","type":"coran","ref":"17:15","src":"Coran 17:15 · Al-Isra","title":"Pas de châtiment avant un messager","verses":[{"n":15,"ar":"مَّنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبۡعَثَ رَسُولٗا","fr":"Quiconque prend le droit chemin ne le prend que pour lui-même; et quiconque s'égare, ne s'égare qu'à son propre détriment. Et nul ne portera le fardeau d'autrui. Et Nous n'avons jamais puni [un peuple] avant de [lui] avoir envoyé un Messager"}],"themes":["justice","choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/17/15"},{"id":"q4-40","type":"coran","ref":"4:40","src":"Coran 4:40 · An-Nisa","title":"Allah ne lèse personne, fût-ce du poids d'un atome","verses":[{"n":40,"ar":"إِنَّ ٱللَّهَ لَا يَظۡلِمُ مِثۡقَالَ ذَرَّةٖۖ وَإِن تَكُ حَسَنَةٗ يُضَٰعِفۡهَا وَيُؤۡتِ مِن لَّدُنۡهُ أَجۡرًا عَظِيمٗا","fr":"Certes, Allah ne lèse (personne), fût-ce du poids d'un atome. S'il est une bonne action, Il la double, et accorde une grosse récompense de Sa part"}],"themes":["justice"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/4/40"},{"id":"q99-7-8","type":"coran","ref":"99:7-8","src":"Coran 99:7-8 · Az-Zalzalah","title":"Le poids d'un atome de bien, le poids d'un atome de mal","verses":[{"n":7,"ar":"فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ","fr":"Quiconque fait un bien fût-ce du poids d'un atome, le verra"},{"n":8,"ar":"وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ","fr":"et quiconque fait un mal fût-ce du poids d'un atome, le verra"}],"themes":["justice","choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/99/7-8"},{"id":"q41-46","type":"coran","ref":"41:46","src":"Coran 41:46 · Fussilat","title":"Ton Seigneur n’est point injuste","verses":[{"n":46,"ar":"مَّنۡ عَمِلَ صَٰلِحٗا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَآءَ فَعَلَيۡهَاۗ وَمَا رَبُّكَ بِظَلَّـٰمٖ لِّلۡعَبِيدِ","fr":"Quiconque fait une bonne œuvre, c'est pour son bien. Et quiconque fait le mal, il le fait à ses dépens. Ton Seigneur, cependant, n'est point injuste envers les serviteurs"}],"themes":["justice","choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/41/46"},{"id":"q6-148-149","type":"coran","ref":"6:148-149","src":"Coran 6:148-149 · Al-An'am","title":"« Si Allah avait voulu, nous n’aurions pas… »","verses":[{"n":148,"ar":"سَيَقُولُ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكۡنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن شَيۡءٖۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ حَتَّىٰ ذَاقُواْ بَأۡسَنَاۗ قُلۡ هَلۡ عِندَكُم مِّنۡ عِلۡمٖ فَتُخۡرِجُوهُ لَنَآۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ أَنتُمۡ إِلَّا تَخۡرُصُونَ","fr":"Ceux qui ont associé diront: «Si Allah avait voulu, nous ne Lui aurions pas donné des associés, nos ancêtres non plus et nous n'aurions rien déclaré interdit.» Ainsi leurs prédécesseurs traitaient de menteurs (les messagers) jusqu'à ce qu'ils eurent goûté Notre rigueur. Dis: «Avez-vous quelque science à nous produire? Vous ne suivez que la conjecture et ne faites que mentir»"},{"n":149,"ar":"قُلۡ فَلِلَّهِ ٱلۡحُجَّةُ ٱلۡبَٰلِغَةُۖ فَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ","fr":"Dis: «L'argument décisif appartient à Allah. S'Il avait voulu certainement Il vous aurait tous guidés. (sur le droit chemin)"}],"themes":["excuse"],"note":"Les polythéistes invoquaient le destin pour justifier leur faute : le Coran leur répond que c'est une conjecture sans science.","grade":"Coran","level":"coran","link":"https://quran.com/6/148-149"},{"id":"q18-54","type":"coran","ref":"18:54","src":"Coran 18:54 · Al-Kahf","title":"L'homme est le plus grand disputeur","verses":[{"n":54,"ar":"وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٖۚ وَكَانَ ٱلۡإِنسَٰنُ أَكۡثَرَ شَيۡءٖ جَدَلٗا","fr":"Et assurément, Nous avons déployé pour les gens, dans ce Coran, toutes sortes d'exemples. L'homme cependant, est de tous les êtres le plus grand disputeur"}],"themes":["excuse"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/18/54"},{"id":"q3-154","type":"coran","ref":"3:154","src":"Coran 3:154 · Ali 'Imran","title":"Eussiez-vous été dans vos maisons…","verses":[{"n":154,"ar":"ثُمَّ أَنزَلَ عَلَيۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةٗ نُّعَاسٗا يَغۡشَىٰ طَآئِفَةٗ مِّنكُمۡۖ وَطَآئِفَةٞ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ يَظُنُّونَ بِٱللَّهِ غَيۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَٰهِلِيَّةِۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءٖۗ قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ يُخۡفُونَ فِيٓ أَنفُسِهِم مَّا لَا يُبۡدُونَ لَكَۖ يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ مَّا قُتِلۡنَا هَٰهُنَاۗ قُل لَّوۡ كُنتُمۡ فِي بُيُوتِكُمۡ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ وَلِيَبۡتَلِيَ ٱللَّهُ مَا فِي صُدُورِكُمۡ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمۡۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ","fr":"Puis Il fit descendre sur vous, après l'angoisse, la tranquillité, un sommeil qui enveloppa une partie d'entre vous, tandis qu'une autre partie était soucieuse pour elle-même et avait des pensées sur Allah non conformes à la vérité, des pensées dignes de l'époque de l'Ignorance. - Ils disaient: «Est-ce que nous avons une part dans cette affaire?» Dis: «L'affaire toute entière est à Allah.» Ce qu'ils ne te révèlent pas, ils le cachent en eux-mêmes: «Si nous avions eu un choix quelconque dans cette affaire, disent-ils, Nous n'aurions pas été tués ici.» Dis: «Eussiez-vous été dans vos maisons, ceux pour qui la mort était décrétée seraient sortis pour l'endroit où la mort les attendait. Ceci afin qu'Allah éprouve ce que vous avez dans vos poitrines, et qu'Il purifie ce que vous avez dans vos cœurs. Et Allah connaît ce qu'il y a dans les cœurs"}],"themes":["vie","excuse"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/3/154"},{"id":"q3-156","type":"coran","ref":"3:156","src":"Coran 3:156 · Ali 'Imran","title":"Ne dites pas : « S’ils étaient restés chez nous… »","verses":[{"n":156,"ar":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ كَفَرُواْ وَقَالُواْ لِإِخۡوَٰنِهِمۡ إِذَا ضَرَبُواْ فِي ٱلۡأَرۡضِ أَوۡ كَانُواْ غُزّٗى لَّوۡ كَانُواْ عِندَنَا مَا مَاتُواْ وَمَا قُتِلُواْ لِيَجۡعَلَ ٱللَّهُ ذَٰلِكَ حَسۡرَةٗ فِي قُلُوبِهِمۡۗ وَٱللَّهُ يُحۡيِۦ وَيُمِيتُۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ","fr":"O les croyants! Ne soyez pas comme ces mécréants qui dirent à propos de leurs frères partis en voyage ou pour combattre: «S'ils étaient chez nous, ils ne seraient pas morts, et ils n'auraient pas été tués.» Allah en fit un sujet de regret dans leurs cœurs. C'est Allah qui donne la vie et la mort. Et Allah observe bien ce que vous faites"}],"themes":["excuse","vie"],"note":"Le « si seulement » sur un décret accompli ne ramène rien et laisse un regret dans le cœur.","grade":"Coran","level":"coran","link":"https://quran.com/3/156"},{"id":"q92-5-10","type":"coran","ref":"92:5-10","src":"Coran 92:5-10 · Al-Layl","title":"Nous lui faciliterons la voie","verses":[{"n":5,"ar":"فَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ","fr":"Celui qui donne et craint (Allah)"},{"n":6,"ar":"وَصَدَّقَ بِٱلۡحُسۡنَىٰ","fr":"et déclare véridique la plus belle récompense"},{"n":7,"ar":"فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ","fr":"Nous lui faciliterons la voie au plus grand bonheur"},{"n":8,"ar":"وَأَمَّا مَنۢ بَخِلَ وَٱسۡتَغۡنَىٰ","fr":"Et quant à celui qui est avare, se dispense (de l'adoration d'Allah)"},{"n":9,"ar":"وَكَذَّبَ بِٱلۡحُسۡنَىٰ","fr":"et traite de mensonge la plus belle récompense"},{"n":10,"ar":"فَسَنُيَسِّرُهُۥ لِلۡعُسۡرَىٰ","fr":"Nous lui faciliterons la voie à la plus grande difficulté"}],"themes":["choix","hidaya"],"note":"Récité par le Prophète ﷺ pour expliquer : « Œuvrez, chacun se voit faciliter… »","grade":"Coran","level":"coran","link":"https://quran.com/92/5-10"},{"id":"q61-5","type":"coran","ref":"61:5","src":"Coran 61:5 · As-Saf","title":"Quand ils dévièrent, Allah fit dévier leurs cœurs","verses":[{"n":5,"ar":"وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ لِمَ تُؤۡذُونَنِي وَقَد تَّعۡلَمُونَ أَنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡۖ فَلَمَّا زَاغُوٓاْ أَزَاغَ ٱللَّهُ قُلُوبَهُمۡۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ","fr":"Et quand Moïse dit à son peuple: «O mon peuple! Pourquoi me maltraitez-vous alors que vous savez que je suis vraiment le Messager d'Allah [envoyé] à vous?» Puis quand ils dévièrent, Allah fit dévier leurs cœurs, car Allah ne guide pas les gens pervers"}],"themes":["hidaya","justice"],"note":"L'égarement vient en conséquence d'un choix : ils ont dévié d'abord.","grade":"Coran","level":"coran","link":"https://quran.com/61/5"},{"id":"q2-26","type":"coran","ref":"2:26","src":"Coran 2:26 · Al-Baqarah","title":"Il n'égare par cela que les pervers","verses":[{"n":26,"ar":"۞إِنَّ ٱللَّهَ لَا يَسۡتَحۡيِۦٓ أَن يَضۡرِبَ مَثَلٗا مَّا بَعُوضَةٗ فَمَا فَوۡقَهَاۚ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ فَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ وَأَمَّا ٱلَّذِينَ كَفَرُواْ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۘ يُضِلُّ بِهِۦ كَثِيرٗا وَيَهۡدِي بِهِۦ كَثِيرٗاۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلۡفَٰسِقِينَ","fr":"Certes, Allah ne se gêne point de citer en exemple n'importe quoi: un moustique ou quoi que ce soit au-dessus; quant aux croyants, ils savent bien qu'il s'agit de la vérité venant de la part de leur Seigneur; quant aux infidèles, ils se demandent «Qu'a voulu dire Allah par un tel exemple?» Par cela, nombreux sont ceux qu'Il égare et nombreux sont ceux qu'Il guide; mais Il n'égare par cela que les pervers"}],"themes":["hidaya","justice"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/26"},{"id":"q9-115","type":"coran","ref":"9:115","src":"Coran 9:115 · At-Tawbah","title":"Allah n'égare pas un peuple sans lui avoir montré","verses":[{"n":115,"ar":"وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوۡمَۢا بَعۡدَ إِذۡ هَدَىٰهُمۡ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمٌ","fr":"Allah n'est point tel à égarer un peuple après qu'Il les a guidés, jusqu'à ce qu'Il leur ait montré clairement ce qu'ils doivent éviter. Certes, Allah est Omniscient"}],"themes":["hidaya","justice"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/9/115"},{"id":"q29-69","type":"coran","ref":"29:69","src":"Coran 29:69 · Al-'Ankabut","title":"Ceux qui luttent pour Nous, Nous les guiderons","verses":[{"n":69,"ar":"وَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِينَ","fr":"Et quant à ceux qui luttent pour Notre cause, Nous les guiderons certes sur Nos sentiers. Allah est en vérité avec les bienfaisants"}],"themes":["hidaya","effort"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/29/69"},{"id":"q47-17","type":"coran","ref":"47:17","src":"Coran 47:17 · Muhammad","title":"Il augmente la guidée de ceux qui se guident","verses":[{"n":17,"ar":"وَٱلَّذِينَ ٱهۡتَدَوۡاْ زَادَهُمۡ هُدٗى وَءَاتَىٰهُمۡ تَقۡوَىٰهُمۡ","fr":"Quant à ceux qui se mirent sur la bonne voie, Il les guida encore plus et leur inspira leur piété"}],"themes":["hidaya"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/47/17"},{"id":"q14-27","type":"coran","ref":"14:27","src":"Coran 14:27 · Ibrahim","title":"Allah affermit les croyants par une parole ferme","verses":[{"n":27,"ar":"يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَيُضِلُّ ٱللَّهُ ٱلظَّـٰلِمِينَۚ وَيَفۡعَلُ ٱللَّهُ مَا يَشَآءُ","fr":"Allah affermit les croyants par une parole ferme, dans la vie présente et dans l'au-delà. Tandis qu'Il égare les injustes. Et Allah fait ce qu'Il veut"}],"themes":["hidaya"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/14/27"},{"id":"q28-56","type":"coran","ref":"28:56","src":"Coran 28:56 · Al-Qasas","title":"Tu ne guides pas qui tu aimes","verses":[{"n":56,"ar":"إِنَّكَ لَا تَهۡدِي مَنۡ أَحۡبَبۡتَ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ","fr":"Tu [Muhammad] ne diriges pas celui que tu aimes: mais c'est Allah qui guide qui Il veut. Il connaît mieux cependant les bien-guidés"}],"themes":["hidaya"],"note":"Guider le cœur (la réussite, tawfîq) n'appartient qu'à Allah.","grade":"Coran","level":"coran","link":"https://quran.com/28/56"},{"id":"q42-52","type":"coran","ref":"42:52","src":"Coran 42:52 · Ash-Shuraa","title":"Et tu guides vers un chemin droit","verses":[{"n":52,"ar":"وَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ رُوحٗا مِّنۡ أَمۡرِنَاۚ مَا كُنتَ تَدۡرِي مَا ٱلۡكِتَٰبُ وَلَا ٱلۡإِيمَٰنُ وَلَٰكِن جَعَلۡنَٰهُ نُورٗا نَّهۡدِي بِهِۦ مَن نَّشَآءُ مِنۡ عِبَادِنَاۚ وَإِنَّكَ لَتَهۡدِيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","fr":"Et c'est ainsi que Nous t'avons révélé un esprit [le Coran] provenant de Notre ordre. Tu n'avais aucune connaissance du Livre ni de la foi; mais Nous en avons fait une lumière par laquelle Nous guidons qui Nous voulons parmi Nos serviteurs. Et en vérité tu guides vers un chemin droit"}],"themes":["hidaya"],"note":"Montrer le chemin (guidée d'explication) est confié au Prophète ﷺ et aux croyants.","grade":"Coran","level":"coran","link":"https://quran.com/42/52"},{"id":"q3-8","type":"coran","ref":"3:8","src":"Coran 3:8 · Ali 'Imran","title":"Ne laisse pas dévier nos cœurs","verses":[{"n":8,"ar":"رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ","fr":"«Seigneur! Ne laisse pas dévier nos cœurs après que Tu nous aies guidés; et accorde-nous Ta miséricorde. C'est Toi, certes, le Grand Donateur"}],"themes":["hidaya","dua"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/3/8"},{"id":"q64-16","type":"coran","ref":"64:16","src":"Coran 64:16 · At-Taghabun","title":"Craignez Allah autant que vous pouvez","verses":[{"n":16,"ar":"فَٱتَّقُواْ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُواْ وَأَطِيعُواْ وَأَنفِقُواْ خَيۡرٗا لِّأَنفُسِكُمۡۗ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","fr":"Craignez Allah, donc autant que vous pouvez, écoutez, obéissez et faites largesses. Ce sera un bien pour vous. Et quiconque a été protégé contre sa propre avidité... ceux-là sont ceux qui réussissent"}],"themes":["effort","choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/64/16"},{"id":"q67-15","type":"coran","ref":"67:15","src":"Coran 67:15 · Al-Mulk","title":"Parcourez la terre et mangez de Sa subsistance","verses":[{"n":15,"ar":"هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولٗا فَٱمۡشُواْ فِي مَنَاكِبِهَا وَكُلُواْ مِن رِّزۡقِهِۦۖ وَإِلَيۡهِ ٱلنُّشُورُ","fr":"C'est Lui qui vous a soumis la terre: parcourez donc ses grandes étendues. Mangez de ce qu'Il vous fournit. Vers Lui est la Résurrection"}],"themes":["effort","vie"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/67/15"},{"id":"q62-10","type":"coran","ref":"62:10","src":"Coran 62:10 · Al-Jumu'ah","title":"Dispersez-vous et recherchez la grâce d’Allah","verses":[{"n":10,"ar":"فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ","fr":"Puis quand la Salât est achevée, dispersez-vous sur terre et recherchez [quelque effet] de la grâce d'Allah, et invoquez beaucoup Allah afin que vous réussissiez"}],"themes":["effort","vie"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/62/10"},{"id":"q2-195","type":"coran","ref":"2:195","src":"Coran 2:195 · Al-Baqarah","title":"Ne vous jetez pas dans la destruction","verses":[{"n":195,"ar":"وَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ وَأَحۡسِنُوٓاْۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ","fr":"Et dépensez dans le sentier d'Allah. Et ne vous jetez pas par vos propres mains dans la destruction. Et faites le bien. Car Allah aime les bienfaisants"}],"themes":["effort"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/195"},{"id":"q4-71","type":"coran","ref":"4:71","src":"Coran 4:71 · An-Nisa","title":"Prenez vos précautions","verses":[{"n":71,"ar":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ خُذُواْ حِذۡرَكُمۡ فَٱنفِرُواْ ثُبَاتٍ أَوِ ٱنفِرُواْ جَمِيعٗا","fr":"O les croyants! Prenez vos précautions et partez en expédition par détachements ou en masse"}],"themes":["effort"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/4/71"},{"id":"q8-60","type":"coran","ref":"8:60","src":"Coran 8:60 · Al-Anfal","title":"Préparez tout ce que vous pouvez","verses":[{"n":60,"ar":"وَأَعِدُّواْ لَهُم مَّا ٱسۡتَطَعۡتُم مِّن قُوَّةٖ وَمِن رِّبَاطِ ٱلۡخَيۡلِ تُرۡهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمۡ وَءَاخَرِينَ مِن دُونِهِمۡ لَا تَعۡلَمُونَهُمُ ٱللَّهُ يَعۡلَمُهُمۡۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فِي سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ","fr":"Et préparez [pour lutter] contre eux tout ce que vous pouvez comme force et comme cavalerie équipée, afin d'effrayer l'ennemi d'Allah et le vôtre, et d'autres encore que vous ne connaissez pas en dehors de ceux-ci mais qu'Allah connaît. Et tout ce que vous dépensez dans le sentier d'Allah vous sera remboursé pleinement et vous ne serez point lésés"}],"themes":["effort"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/8/60"},{"id":"q3-159","type":"coran","ref":"3:159","src":"Coran 3:159 · Ali 'Imran","title":"Consulte, décide, puis confie-toi à Allah","verses":[{"n":159,"ar":"فَبِمَا رَحۡمَةٖ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ","fr":"C'est par quelque miséricorde de la part d'Allah que tu (Muhammad) as été si doux envers eux! Mais si tu étais rude, au cœur dur, ils se seraient enfuis de ton entourage. Pardonne-leur donc, et implore pour eux le pardon (d'Allah). Et consulte-les à propos des affaires; puis une fois que tu t'es décidé, confie-toi donc à Allah, Allah aime, en vérité, ceux qui Lui font confiance"}],"themes":["tawakkul","effort"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/3/159"},{"id":"q65-2-3","type":"coran","ref":"65:2-3","src":"Coran 65:2-3 · At-Talaq","title":"Quiconque place sa confiance en Allah, Il lui suffit","verses":[{"n":2,"ar":"فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفٖ وَأَشۡهِدُواْ ذَوَيۡ عَدۡلٖ مِّنكُمۡ وَأَقِيمُواْ ٱلشَّهَٰدَةَ لِلَّهِۚ ذَٰلِكُمۡ يُوعَظُ بِهِۦ مَن كَانَ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا","fr":"Puis quand elles atteignent le terme prescrit, retenez-les de façon convenable, ou séparez-vous d'elles de façon convenable; et prenez deux hommes intègres parmi vous comme témoins. Et acquittez-vous du témoignage envers Allah. Voilà ce à quoi est exhorté celui qui croit en Allah et au Jour dernier. Et quiconque craint Allah, Il Lui donnera une issue favorable"},{"n":3,"ar":"وَيَرۡزُقۡهُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُۚ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓۚ إِنَّ ٱللَّهَ بَٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَيۡءٖ قَدۡرٗا","fr":"et lui accordera Ses dons par [des moyens] sur lesquels il ne comptait pas. Et quiconque place sa confiance en Allah, Il [Allah] lui suffit. Allah atteint ce qu'Il Se propose, et Allah a assigné une mesure à chaque chose"}],"themes":["tawakkul","vie"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/65/2-3"},{"id":"q3-173","type":"coran","ref":"3:173","src":"Coran 3:173 · Ali 'Imran","title":"« Allah nous suffit »","verses":[{"n":173,"ar":"ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ","fr":"Certes ceux auxquels l'on disait: «Les gens se sont rassemblés contre vous; craignez-les» - cela accrut leur foi - et ils dirent: «Allah nous suffit; Il est notre meilleur garant»"}],"themes":["tawakkul"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/3/173"},{"id":"q9-40","type":"coran","ref":"9:40","src":"Coran 9:40 · At-Tawbah","title":"« Ne t’afflige pas, Allah est avec nous »","verses":[{"n":40,"ar":"إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودٖ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ","fr":"Si vous ne lui portez pas secours... Allah l'a déjà secouru, lorsque ceux qui avaient mécru l'avaient banni, deuxième de deux. Quand ils étaient dans la grotte et qu'il disait à son compagnon: «Ne t'afflige pas, car Allah est avec nous.» Allah fit alors descendre sur Lui Sa sérénité «Sa sakîna» et le soutint de soldats (Anges) que vous ne voyiez pas, et Il abaissa ainsi la parole des mécréants, tandis que la parole d'Allah eut le dessus. Et Allah est Puissant et Sage"}],"themes":["tawakkul"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/9/40"},{"id":"q14-12","type":"coran","ref":"14:12","src":"Coran 14:12 · Ibrahim","title":"Comment ne pas Lui faire confiance ?","verses":[{"n":12,"ar":"وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدۡ هَدَىٰنَا سُبُلَنَاۚ وَلَنَصۡبِرَنَّ عَلَىٰ مَآ ءَاذَيۡتُمُونَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ","fr":"Et qu'aurions-nous à ne pas placer notre confiance en Allah, alors qu'Il nous a guidés sur les sentiers [que nous devions suivre]? Nous endurerons sûrement la persécution que vous nous infligez. Et ceux qui ont confiance en Allah s'en remettent entièrement à Lui.»"}],"themes":["tawakkul","sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/14/12"},{"id":"q25-58","type":"coran","ref":"25:58","src":"Coran 25:58 · Al-Furqan","title":"Confie-toi au Vivant qui ne meurt pas","verses":[{"n":58,"ar":"وَتَوَكَّلۡ عَلَى ٱلۡحَيِّ ٱلَّذِي لَا يَمُوتُ وَسَبِّحۡ بِحَمۡدِهِۦۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا","fr":"Et place ta confiance en Le Vivant qui ne meurt jamais. Et par Sa louange, glorifie-Le. Il suffit comme Parfait Connaisseur des péchés de Ses serviteurs"}],"themes":["tawakkul"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/25/58"},{"id":"q11-88","type":"coran","ref":"11:88","src":"Coran 11:88 · Hud","title":"Ma réussite ne dépend que d’Allah","verses":[{"n":88,"ar":"قَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَرَزَقَنِي مِنۡهُ رِزۡقًا حَسَنٗاۚ وَمَآ أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ مَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ","fr":"Il dit: «O mon peuple, voyez-vous si je me base sur une preuve évidente émanant de mon Seigneur, et s'Il m'attribue de Sa part une excellente donation?... Je ne veux nullement faire ce que je vous interdis. Je ne veux que la réforme, autant que je le puis. Et ma réussite ne dépend que d'Allah. En Lui je place ma confiance, et c'est vers Lui que je reviens repentant"}],"themes":["tawakkul","effort"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/11/88"},{"id":"q12-67-68","type":"coran","ref":"12:67-68","src":"Coran 12:67-68 · Yusuf","title":"Jacob : la précaution et la confiance","verses":[{"n":67,"ar":"وَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابٖ وَٰحِدٖ وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبٖ مُّتَفَرِّقَةٖۖ وَمَآ أُغۡنِي عَنكُم مِّنَ ٱللَّهِ مِن شَيۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ","fr":"Et il dit: «O mes fils, n'entrez pas par une seule porte, mais entrez par portes séparées. Je ne peux cependant vous être d'aucune utilité contre les desseins d'Allah. La décision n'appartient qu'à Allah: en Lui je place ma confiance. Et que ceux qui placent leur confiance la placent en Lui»"},{"n":68,"ar":"وَلَمَّا دَخَلُواْ مِنۡ حَيۡثُ أَمَرَهُمۡ أَبُوهُم مَّا كَانَ يُغۡنِي عَنۡهُم مِّنَ ٱللَّهِ مِن شَيۡءٍ إِلَّا حَاجَةٗ فِي نَفۡسِ يَعۡقُوبَ قَضَىٰهَاۚ وَإِنَّهُۥ لَذُو عِلۡمٖ لِّمَا عَلَّمۡنَٰهُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ","fr":"Etant entrés comme leur père le leur avait commandé [cela] ne leur servit à rien contre (les décrets d') Allah. Ce n'était [au reste] qu'une précaution que Jacob avait jugé [de leur recommander]. Il avait pleine connaissance de ce que Nous lui avions enseigné. Mais la plupart des gens ne savent pas"}],"themes":["effort","tawakkul"],"note":"Jacob conseille une précaution, puis rappelle qu'elle ne protège de rien sans Allah.","grade":"Coran","level":"coran","link":"https://quran.com/12/67-68"},{"id":"q40-60","type":"coran","ref":"40:60","src":"Coran 40:60 · Ghafir","title":"Appelez-Moi, Je vous répondrai","verses":[{"n":60,"ar":"وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ","fr":"Et votre Seigneur dit: «Appelez-Moi, Je vous répondrai. Ceux qui, par orgueil, se refusent à M'adorer entreront bientôt dans l'Enfer, humiliés»"}],"themes":["dua"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/40/60"},{"id":"q2-186","type":"coran","ref":"2:186","src":"Coran 2:186 · Al-Baqarah","title":"Je suis tout proche","verses":[{"n":186,"ar":"وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ","fr":"Et quand Mes serviteurs t'interrogent sur Moi.. alors Je suis tout proche: Je réponds à l'appel de celui qui Me prie quand il Me prie. Qu'ils répondent à Mon appel, et qu'ils croient en Moi, afin qu'ils soient bien guidés"}],"themes":["dua"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/186"},{"id":"q2-45","type":"coran","ref":"2:45","src":"Coran 2:45 · Al-Baqarah","title":"Cherchez secours dans la patience et la prière","verses":[{"n":45,"ar":"وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ","fr":"Et cherchez secours dans l'endurance et la salât: certes, la Salât est une lourde obligation, sauf pour les humbles"}],"themes":["sabr","dua"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/45"},{"id":"q2-153","type":"coran","ref":"2:153","src":"Coran 2:153 · Al-Baqarah","title":"Allah est avec les endurants","verses":[{"n":153,"ar":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ","fr":"O les croyants! Cherchez secours dans l'endurance et la Salât. Car Allah est avec ceux qui sont endurants"}],"themes":["sabr","dua"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/153"},{"id":"q2-155-157","type":"coran","ref":"2:155-157","src":"Coran 2:155-157 · Al-Baqarah","title":"Nous vous éprouverons","verses":[{"n":155,"ar":"وَلَنَبۡلُوَنَّكُم بِشَيۡءٖ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصٖ مِّنَ ٱلۡأَمۡوَٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَٰتِۗ وَبَشِّرِ ٱلصَّـٰبِرِينَ","fr":"Très certainement, Nous vous éprouverons par un peu de peur, de faim et de diminution de biens, de personnes et de fruits. Et fais la bonne annonce aux endurants"},{"n":156,"ar":"ٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ","fr":"qui disent, quand un malheur les atteint: «Certes nous sommes à Allah, et c'est à Lui que nous retournerons"},{"n":157,"ar":"أُوْلَـٰٓئِكَ عَلَيۡهِمۡ صَلَوَٰتٞ مِّن رَّبِّهِمۡ وَرَحۡمَةٞۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُهۡتَدُونَ","fr":"Ceux-là reçoivent des bénédictions de leur Seigneur, ainsi que la miséricorde; et ceux-là sont les biens guidés"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/155-157"},{"id":"q64-11","type":"coran","ref":"64:11","src":"Coran 64:11 · At-Taghabun","title":"Nul malheur sans la permission d'Allah","verses":[{"n":11,"ar":"مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ يَهۡدِ قَلۡبَهُۥۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ","fr":"Nul malheur n'atteint [l'homme] que par la permission d'Allah. Et quiconque croit en Allah, [Allah] guide son cœur. Allah est Omniscient"}],"themes":["sabr","mashia"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/64/11"},{"id":"q2-214","type":"coran","ref":"2:214","src":"Coran 2:214 · Al-Baqarah","title":"Quand viendra le secours d’Allah ?","verses":[{"n":214,"ar":"أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ","fr":"Pensez-vous entrer au Paradis alors que vous n'avez pas encore subi des épreuves semblables à celles que subirent ceux qui vécurent avant vous? Misère et maladie les avaient touchés; et ils furent secoués jusqu'à ce que le Messager, et avec lui, ceux qui avaient cru, se fussent écriés: «Quand viendra le secours d'Allah?» - Quoi! le secours d'Allah est sûrement proche"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/214"},{"id":"q3-142","type":"coran","ref":"3:142","src":"Coran 3:142 · Ali 'Imran","title":"Le Paradis sans épreuve ?","verses":[{"n":142,"ar":"أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَيَعۡلَمَ ٱلصَّـٰبِرِينَ","fr":"Comptez-vous entrer au Paradis sans qu'Allah ne distingue parmi vous ceux qui luttent et qui sont endurants"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/3/142"},{"id":"q29-2-3","type":"coran","ref":"29:2-3","src":"Coran 29:2-3 · Al-'Ankabut","title":"Les gens pensent-ils qu’on les laissera dire « nous croyons » ?","verses":[{"n":2,"ar":"أَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ","fr":"Est-ce que les gens pensent qu'on les laissera dire: «Nous croyons!» sans les éprouver"},{"n":3,"ar":"وَلَقَدۡ فَتَنَّا ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُواْ وَلَيَعۡلَمَنَّ ٱلۡكَٰذِبِينَ","fr":"Certes, Nous avons éprouvé ceux qui ont vécu avant eux; [Ainsi] Allah connaît ceux qui disent la vérité et ceux qui mentent"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/29/2-3"},{"id":"q47-31","type":"coran","ref":"47:31","src":"Coran 47:31 · Muhammad","title":"Nous vous éprouverons afin de distinguer","verses":[{"n":31,"ar":"وَلَنَبۡلُوَنَّكُمۡ حَتَّىٰ نَعۡلَمَ ٱلۡمُجَٰهِدِينَ مِنكُمۡ وَٱلصَّـٰبِرِينَ وَنَبۡلُوَاْ أَخۡبَارَكُمۡ","fr":"Nous vous éprouverons certes afin de distinguer ceux d'entre vous qui luttent [pour la cause d'Allah] et qui endurent, et afin d'éprouver [faire apparaître] vos nouvelles"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/47/31"},{"id":"q67-2","type":"coran","ref":"67:2","src":"Coran 67:2 · Al-Mulk","title":"La vie et la mort pour éprouver qui agit le mieux","verses":[{"n":2,"ar":"ٱلَّذِي خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَيَوٰةَ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡغَفُورُ","fr":"Celui qui a créé la mort et la vie afin de vous éprouver (et de savoir) qui de vous est le meilleur en œuvre, et c'est Lui le Puissant, le Pardonneur"}],"themes":["sabr","choix"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/67/2"},{"id":"q21-35","type":"coran","ref":"21:35","src":"Coran 21:35 · Al-Anbya","title":"Éprouvés par le mal et par le bien","verses":[{"n":35,"ar":"كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ فِتۡنَةٗۖ وَإِلَيۡنَا تُرۡجَعُونَ","fr":"Toute âme doit goûter la mort. Nous vous éprouverons par le mal et par le bien [à titre] de tentation. Et c'est à Nous que vous serez ramenés"}],"themes":["sabr","shukr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/21/35"},{"id":"q94-5-6","type":"coran","ref":"94:5-6","src":"Coran 94:5-6 · Ash-Sharh","title":"Avec la difficulté, une facilité","verses":[{"n":5,"ar":"فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا","fr":"A côté de la difficulté est, certes, une facilité"},{"n":6,"ar":"إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرٗا","fr":"A côté de la difficulté est, certes, une facilité"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/94/5-6"},{"id":"q65-7","type":"coran","ref":"65:7","src":"Coran 65:7 · At-Talaq","title":"Allah fera succéder l'aisance à la gêne","verses":[{"n":7,"ar":"لِيُنفِقۡ ذُو سَعَةٖ مِّن سَعَتِهِۦۖ وَمَن قُدِرَ عَلَيۡهِ رِزۡقُهُۥ فَلۡيُنفِقۡ مِمَّآ ءَاتَىٰهُ ٱللَّهُۚ لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَآ ءَاتَىٰهَاۚ سَيَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرٖ يُسۡرٗا","fr":"Que celui qui est aisé dépense de sa fortune; et que celui dont les biens sont restreints dépense selon ce qu'Allah lui a accordé. Allah n'impose à personne que selon ce qu'Il lui a donné, et Allah fera succéder l'aisance à la gêne"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/65/7"},{"id":"q70-5","type":"coran","ref":"70:5","src":"Coran 70:5 · Al-Ma'arij","title":"Une belle patience","verses":[{"n":5,"ar":"فَٱصۡبِرۡ صَبۡرٗا جَمِيلًا","fr":"Supporte donc, d'une belle patience"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/70/5"},{"id":"q39-10","type":"coran","ref":"39:10","src":"Coran 39:10 · Az-Zumar","title":"Les endurants, récompensés sans compter","verses":[{"n":10,"ar":"قُلۡ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ رَبَّكُمۡۚ لِلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۗ وَأَرۡضُ ٱللَّهِ وَٰسِعَةٌۗ إِنَّمَا يُوَفَّى ٱلصَّـٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابٖ","fr":"Dis: «O Mes serviteurs qui avez cru! Craignez votre Seigneur». Ceux qui ici-bas font le bien, auront une bonne [récompense]. La terre d'Allah est vaste et les endurants auront leur pleine récompense sans compter"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/39/10"},{"id":"q16-127","type":"coran","ref":"16:127","src":"Coran 16:127 · An-Nahl","title":"Ta patience ne vient qu'avec Allah","verses":[{"n":127,"ar":"وَٱصۡبِرۡ وَمَا صَبۡرُكَ إِلَّا بِٱللَّهِۚ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُ فِي ضَيۡقٖ مِّمَّا يَمۡكُرُونَ","fr":"Endure! Ton endurance [ne viendra] qu'avec (l'aide) d'Allah. Ne t'afflige pas pour eux. Et ne sois pas angoissé à cause de leurs complots"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/16/127"},{"id":"q31-17","type":"coran","ref":"31:17","src":"Coran 31:17 · Luqman","title":"Endure ce qui t’arrive","verses":[{"n":17,"ar":"يَٰبُنَيَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ إِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ","fr":"O mon enfant accomplis la Salât, commande le convenable, interdis le blâmable et endure ce qui t'arrive avec patience. Telle est la résolution à prendre dans toute entreprise"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/31/17"},{"id":"q8-46","type":"coran","ref":"8:46","src":"Coran 8:46 · Al-Anfal","title":"Soyez endurants","verses":[{"n":46,"ar":"وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ وَتَذۡهَبَ رِيحُكُمۡۖ وَٱصۡبِرُوٓاْۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ","fr":"Et obéissez à Allah et à Son messager; et ne vous disputez pas, sinon vous fléchirez et perdrez votre force. Et soyez endurants, car Allah est avec les endurants"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/8/46"},{"id":"q103-1-3","type":"coran","ref":"103:1-3","src":"Coran 103:1-3 · Al-'Asr","title":"Par le Temps","verses":[{"n":1,"ar":"وَٱلۡعَصۡرِ","fr":"Par le Temps"},{"n":2,"ar":"إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ","fr":"L'homme est certes, en perdition"},{"n":3,"ar":"إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ","fr":"sauf ceux qui croient et accomplissent les bonnes œuvres, s'enjoignent mutuellement la vérité et s'enjoignent mutuellement l'endurance"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/103/1-3"},{"id":"q42-39-43","type":"coran","ref":"42:39-43","src":"Coran 42:39-43 · Ash-Shuraa","title":"Face à l'injustice : se défendre, ou pardonner","verses":[{"n":39,"ar":"وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلۡبَغۡيُ هُمۡ يَنتَصِرُونَ","fr":"et qui, atteints par l'injustice, ripostent"},{"n":40,"ar":"وَجَزَـٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّـٰلِمِينَ","fr":"La sanction d'une mauvaise action est une mauvaise action [une peine] identique. Mais quiconque pardonne et réforme, son salaire incombe à Allah. Il n'aime point les injustes"},{"n":41,"ar":"وَلَمَنِ ٱنتَصَرَ بَعۡدَ ظُلۡمِهِۦ فَأُوْلَـٰٓئِكَ مَا عَلَيۡهِم مِّن سَبِيلٍ","fr":"Quant à ceux qui ripostent après avoir été lésés, ...ceux-là pas de voie (recours légal) contre eux"},{"n":42,"ar":"إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظۡلِمُونَ ٱلنَّاسَ وَيَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۚ أُوْلَـٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ","fr":"il n'y a de voie [de recours] que contre ceux qui lèsent les gens et commettent des abus, contrairement au droit, sur la terre: ceux-là auront un châtiment douloureux"},{"n":43,"ar":"وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنۡ عَزۡمِ ٱلۡأُمُورِ","fr":"Et celui qui endure et pardonne, cela en vérité, fait partie des bonnes dispositions et de la résolution dans les affaires"}],"themes":["sabr","justice"],"note":"Riposter à l'injustice dans la mesure du droit est permis ; endurer et pardonner est plus élevé.","grade":"Coran","level":"coran","link":"https://quran.com/42/39-43"},{"id":"q40-55","type":"coran","ref":"40:55","src":"Coran 40:55 · Ghafir","title":"Endure… et demande pardon pour ton péché","verses":[{"n":55,"ar":"فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ","fr":"Endure donc, car la promesse d'Allah est vérité, implore le pardon pour ton péché et célèbre la gloire et la louange de ton Seigneur, soir et matin"}],"themes":["sabr","tawba"],"note":"Patience face à l'épreuve, pardon face au péché : les deux attitudes dans un seul verset.","grade":"Coran","level":"coran","link":"https://quran.com/40/55"},{"id":"q12-18","type":"coran","ref":"12:18","src":"Coran 12:18 · Yusuf","title":"Jacob : « une belle patience »","verses":[{"n":18,"ar":"وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٖ كَذِبٖۚ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٞۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ","fr":"Ils apportèrent sa tunique tachée d'un faux sang. Il dit: «Vos âmes, plutôt, vous ont suggéré quelque chose... [Il ne me reste plus donc] qu'une belle patience! C'est Allah qu'il faut appeler au secours contre ce que vous racontez!»"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/12/18"},{"id":"q12-83","type":"coran","ref":"12:83","src":"Coran 12:83 · Yusuf","title":"Jacob espère encore","verses":[{"n":83,"ar":"قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٌۖ عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ","fr":"Alors [Jacob] dit: Vos âmes plutôt vous ont inspiré [d'entreprendre] quelque chose!... Oh! belle patience. Il se peut qu'Allah me les ramènera tous les deux. Car c'est Lui l'Omniscient, le Sage»"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/12/83"},{"id":"q12-86","type":"coran","ref":"12:86","src":"Coran 12:86 · Yusuf","title":"Je ne me plains qu'à Allah","verses":[{"n":86,"ar":"قَالَ إِنَّمَآ أَشۡكُواْ بَثِّي وَحُزۡنِيٓ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ","fr":"Il dit: «Je ne me plains qu'à Allah de mon déchirement et de mon chagrin. Et, je sais de la part d'Allah, ce que vous ne savez pas"}],"themes":["sabr","dua"],"note":"Se plaindre à Allah ne contredit pas la patience ; c'est se plaindre d'Allah aux gens qui la contredit.","grade":"Coran","level":"coran","link":"https://quran.com/12/86"},{"id":"q12-87","type":"coran","ref":"12:87","src":"Coran 12:87 · Yusuf","title":"Ne désespérez pas de la miséricorde d’Allah","verses":[{"n":87,"ar":"يَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ","fr":"O mes fils! Partez et enquérez-vous de Joseph et de son frère. Et ne désespérez pas de la miséricorde d'Allah. Ce sont seulement les gens mécréants qui désespèrent de la miséricorde d'Allah»"}],"themes":["sabr","tawakkul"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/12/87"},{"id":"q15-56","type":"coran","ref":"15:56","src":"Coran 15:56 · Al-Hijr","title":"Qui désespère, sinon les égarés ?","verses":[{"n":56,"ar":"قَالَ وَمَن يَقۡنَطُ مِن رَّحۡمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ","fr":"Il dit: «Et qui désespère de la miséricorde de son Seigneur, sinon les égarés?»"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/15/56"},{"id":"q12-90","type":"coran","ref":"12:90","src":"Coran 12:90 · Yusuf","title":"Quiconque craint Allah et patiente","verses":[{"n":90,"ar":"قَالُوٓاْ أَءِنَّكَ لَأَنتَ يُوسُفُۖ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِيۖ قَدۡ مَنَّ ٱللَّهُ عَلَيۡنَآۖ إِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ","fr":"Ils dirent: «Est-ce que tu es... Certes, tu es Joseph!» - Il dit: «Je suis Joseph, et voici mon frère. Certes, Allah nous a favorisés. Quiconque craint et patiente... Et très certainement, Allah ne fait pas perdre la récompense des bienfaisants»"}],"themes":["sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/12/90"},{"id":"q12-100","type":"coran","ref":"12:100","src":"Coran 12:100 · Yusuf","title":"Mon Seigneur est plein de douceur pour ce qu’Il veut","verses":[{"n":100,"ar":"وَرَفَعَ أَبَوَيۡهِ عَلَى ٱلۡعَرۡشِ وَخَرُّواْ لَهُۥ سُجَّدٗاۖ وَقَالَ يَـٰٓأَبَتِ هَٰذَا تَأۡوِيلُ رُءۡيَٰيَ مِن قَبۡلُ قَدۡ جَعَلَهَا رَبِّي حَقّٗاۖ وَقَدۡ أَحۡسَنَ بِيٓ إِذۡ أَخۡرَجَنِي مِنَ ٱلسِّجۡنِ وَجَآءَ بِكُم مِّنَ ٱلۡبَدۡوِ مِنۢ بَعۡدِ أَن نَّزَغَ ٱلشَّيۡطَٰنُ بَيۡنِي وَبَيۡنَ إِخۡوَتِيٓۚ إِنَّ رَبِّي لَطِيفٞ لِّمَا يَشَآءُۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ","fr":"Et il éleva ses parents sur le trône, et tous tombèrent devant lui, prosternés. Et il dit: «O mon père, voilà l'interprétation de mon rêve de jadis. Allah l'a bel et bien réalisé... Et Il m'a certainement fait du bien quand Il m'a fait sortir de prison et qu'Il vous a fait venir de la campagne, [du désert], après que le Diable ait suscité la discorde entre mes frères et moi. Mon Seigneur est plein de douceur pour ce qu'Il veut. Et c'est Lui l'Omniscient, le Sage"}],"themes":["hikma"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/12/100"},{"id":"q21-83-84","type":"coran","ref":"21:83-84","src":"Coran 21:83-84 · Al-Anbya","title":"Job : « Le mal m’a touché »","verses":[{"n":83,"ar":"۞وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّـٰحِمِينَ","fr":"Et Job, quand il implora son Seigneur: «Le mal m'a touché. Mais Toi, tu es le plus miséricordieux des miséricordieux»"},{"n":84,"ar":"فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرّٖۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ","fr":"Nous l'exauçâmes, enlevâmes le mal qu'il avait, lui rendîmes les siens et autant qu'eux avec eux, par miséricorde de Notre part et en tant que rappel aux adorateurs"}],"themes":["sabr","dua"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/21/83-84"},{"id":"q38-41-44","type":"coran","ref":"38:41-44","src":"Coran 38:41-44 · Sad","title":"Job : « Frappe la terre de ton pied »","verses":[{"n":41,"ar":"وَٱذۡكُرۡ عَبۡدَنَآ أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلشَّيۡطَٰنُ بِنُصۡبٖ وَعَذَابٍ","fr":"Et rappelle-toi Job, Notre serviteur, lorsqu'il appela son Seigneur: «Le Diable m'a infligé détresse et souffrance»"},{"n":42,"ar":"ٱرۡكُضۡ بِرِجۡلِكَۖ هَٰذَا مُغۡتَسَلُۢ بَارِدٞ وَشَرَابٞ","fr":"Frappe [la terre] de ton pied: voici une eau fraîche pour te laver et voici de quoi boire"},{"n":43,"ar":"وَوَهَبۡنَا لَهُۥٓ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنَّا وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ","fr":"Et Nous lui rendîmes sa famille et la fîmes deux fois plus nombreuse, comme une miséricorde de Notre part et comme un rappel pour les gens doués d'intelligence"},{"n":44,"ar":"وَخُذۡ بِيَدِكَ ضِغۡثٗا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٞ","fr":"«Et prends dans ta main un faisceau de brindilles, puis frappe avec cela. Et ne viole pas ton serment». Oui, Nous l'avons trouvé vraiment endurant. Quel bon serviteur! Sans cesse il se repentait"}],"themes":["sabr","effort"],"note":"Même au cœur de l'épreuve, Allah lui demande un geste : la cause fait partie de la délivrance.","grade":"Coran","level":"coran","link":"https://quran.com/38/41-44"},{"id":"q21-87-88","type":"coran","ref":"21:87-88","src":"Coran 21:87-88 · Al-Anbya","title":"Jonas dans les ténèbres","verses":[{"n":87,"ar":"وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّـٰلِمِينَ","fr":"Et Dû'n-Nûn (Jonas) quand il partit, irrité. Il pensa que Nous N'allions pas l'éprouver. Puis il fit, dans les ténèbres, l'appel que voici: «Pas de divinité à part Toi! Pureté à Toi! J'ai été vraiment du nombre des injustes»"},{"n":88,"ar":"فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ","fr":"Nous l'exauçâmes et le sauvâmes de son angoisse. Et c'est ainsi que Nous sauvons les croyants"}],"themes":["dua","tawba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/21/87-88"},{"id":"q37-143-144","type":"coran","ref":"37:143-144","src":"Coran 37:143-144 · As-Saffat","title":"S'il n'avait pas glorifié Allah…","verses":[{"n":143,"ar":"فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ","fr":"S'il n'avait pas été parmi ceux qui glorifient Allah"},{"n":144,"ar":"لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ","fr":"il serait demeuré dans son ventre jusqu'au jour où l'on sera ressuscité"}],"themes":["dua"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/37/143-144"},{"id":"q19-23-26","type":"coran","ref":"19:23-26","src":"Coran 19:23-26 · Maryam","title":"Marie : « Secoue vers toi le tronc »","verses":[{"n":23,"ar":"فَأَجَآءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ قَالَتۡ يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيٗا مَّنسِيّٗا","fr":"Puis les douleurs de l'enfantement l'amenèrent au tronc du palmier, et elle dit: «Malheur à moi! Que je fusse morte avant cet instant! Et que je fusse totalement oubliée!»"},{"n":24,"ar":"فَنَادَىٰهَا مِن تَحۡتِهَآ أَلَّا تَحۡزَنِي قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِيّٗا","fr":"Alors, il l'appela d'au-dessous d'elle, [lui disant:] «Ne t'afflige pas. Ton Seigneur a placé à tes pieds une source"},{"n":25,"ar":"وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا","fr":"Secoue vers toi le tronc du palmier: il fera tomber sur toi des dattes fraîches et mûres"},{"n":26,"ar":"فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدٗا فَقُولِيٓ إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا","fr":"Mange donc et bois et que ton œil se réjouisse! Si tu vois quelqu'un d'entre les humains, dis [lui:] «Assurément, j'ai voué un jeûne au Tout Miséricordieux: je ne parlerai donc aujourd'hui à aucun être humain»"}],"themes":["effort","sabr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/19/23-26"},{"id":"q2-216","type":"coran","ref":"2:216","src":"Coran 2:216 · Al-Baqarah","title":"Il se peut que vous détestiez une chose qui est un bien","verses":[{"n":216,"ar":"كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تُحِبُّواْ شَيۡـٔٗا وَهُوَ شَرّٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ","fr":"Le combat vous a été prescrit alors qu'il vous est désagréable. Or, il se peut que vous ayez de l'aversion pour une chose alors qu'elle vous est un bien. Et il se peut que vous aimiez une chose alors qu'elle vous est mauvaise. C'est Allah qui sait, alors que vous ne savez pas"}],"themes":["hikma"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/216"},{"id":"q18-79-82","type":"coran","ref":"18:79-82","src":"Coran 18:79-82 · Al-Kahf","title":"Al-Khidr : la sagesse derrière l'apparence","verses":[{"n":79,"ar":"أَمَّا ٱلسَّفِينَةُ فَكَانَتۡ لِمَسَٰكِينَ يَعۡمَلُونَ فِي ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٞ يَأۡخُذُ كُلَّ سَفِينَةٍ غَصۡبٗا","fr":"Pour ce qui est du bateau, il appartenait à des pauvres gens qui travaillaient en mer. Je voulais donc le rendre défectueux, car il y avait derrière eux un roi qui saisissait de force tout bateau"},{"n":80,"ar":"وَأَمَّا ٱلۡغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤۡمِنَيۡنِ فَخَشِينَآ أَن يُرۡهِقَهُمَا طُغۡيَٰنٗا وَكُفۡرٗا","fr":"Quant au garçon, ses père et mère étaient des croyants; nous avons craint qu'il ne leur imposât la rébellion et la mécréance"},{"n":81,"ar":"فَأَرَدۡنَآ أَن يُبۡدِلَهُمَا رَبُّهُمَا خَيۡرٗا مِّنۡهُ زَكَوٰةٗ وَأَقۡرَبَ رُحۡمٗا","fr":"Nous avons donc voulu que leur Seigneur leur accordât en échange un autre plus pur et plus affectueux"},{"n":82,"ar":"وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَٰمَيۡنِ يَتِيمَيۡنِ فِي ٱلۡمَدِينَةِ وَكَانَ تَحۡتَهُۥ كَنزٞ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةٗ مِّن رَّبِّكَۚ وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرٗا","fr":"Et quant au mur, il appartenait à deux garçons orphelins de la ville, et il y avait dessous un trésor à eux; et leur père était un homme vertueux. Ton Seigneur a donc voulu que tous deux atteignent leur maturité et qu'ils extraient, [eux-mêmes] leur trésor, par une miséricorde de ton Seigneur. Je ne l'ai d'ailleurs pas fait de mon propre chef. Voilà l'interprétation de ce que tu n'as pas pu endurer avec patience»"}],"themes":["hikma"],"note":"Le bateau abîmé, le garçon, le mur : derrière chaque événement pénible, une miséricorde que Moïse ne voyait pas.","grade":"Coran","level":"coran","link":"https://quran.com/18/79-82"},{"id":"q3-145","type":"coran","ref":"3:145","src":"Coran 3:145 · Ali 'Imran","title":"Personne ne meurt sans la permission d’Allah","verses":[{"n":145,"ar":"وَمَا كَانَ لِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَٰبٗا مُّؤَجَّلٗاۗ وَمَن يُرِدۡ ثَوَابَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَن يُرِدۡ ثَوَابَ ٱلۡأٓخِرَةِ نُؤۡتِهِۦ مِنۡهَاۚ وَسَنَجۡزِي ٱلشَّـٰكِرِينَ","fr":"Personne ne peut mourir que par la permission d'Allah, et au moment prédéterminé. Quiconque veut la récompense d'ici-bas, Nous lui en donnons. Quiconque veut la récompense de l'au-delà, Nous lui en donnons, et Nous récompenserons bientôt les reconnaissants"}],"themes":["vie","kitaba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/3/145"},{"id":"q7-34","type":"coran","ref":"7:34","src":"Coran 7:34 · Al-A'raf","title":"Ni une heure de retard, ni une heure d’avance","verses":[{"n":34,"ar":"وَلِكُلِّ أُمَّةٍ أَجَلٞۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَأۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ","fr":"Pour chaque communauté il y a un terme. Quand leur terme vient, ils ne peuvent le retarder d'une heure et ils ne peuvent le hâter non plus"}],"themes":["vie"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/7/34"},{"id":"q63-11","type":"coran","ref":"63:11","src":"Coran 63:11 · Al-Munafiqun","title":"Aucun délai quand le terme arrive","verses":[{"n":11,"ar":"وَلَن يُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَآءَ أَجَلُهَاۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ","fr":"Allah cependant n'accorde jamais de délai à une âme dont le terme est arrivé. Et Allah est Parfaitement Connaisseur de ce que vous faites"}],"themes":["vie"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/63/11"},{"id":"q56-60","type":"coran","ref":"56:60","src":"Coran 56:60 · Al-Waqi'ah","title":"Nous avons prédéterminé la mort","verses":[{"n":60,"ar":"نَحۡنُ قَدَّرۡنَا بَيۡنَكُمُ ٱلۡمَوۡتَ وَمَا نَحۡنُ بِمَسۡبُوقِينَ","fr":"Nous avons prédéterminé la mort parmi vous. Nous ne serons point empêchés"}],"themes":["vie"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/56/60"},{"id":"q51-22","type":"coran","ref":"51:22","src":"Coran 51:22 · Adh-Dhariyat","title":"Dans le ciel est votre subsistance","verses":[{"n":22,"ar":"وَفِي ٱلسَّمَآءِ رِزۡقُكُمۡ وَمَا تُوعَدُونَ","fr":"Et il y a dans le ciel votre subsistance et ce qui vous a été promis"}],"themes":["vie"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/51/22"},{"id":"q29-60","type":"coran","ref":"29:60","src":"Coran 29:60 · Al-'Ankabut","title":"Que de bêtes ne portent pas leur nourriture !","verses":[{"n":60,"ar":"وَكَأَيِّن مِّن دَآبَّةٖ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","fr":"Que de bêtes ne se chargent point de leur propre nourriture! C'est Allah qui les nourrit ainsi que vous. Et c'est Lui l'Audient, l'Omniscient"}],"themes":["vie","tawakkul"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/29/60"},{"id":"q42-27","type":"coran","ref":"42:27","src":"Coran 42:27 · Ash-Shuraa","title":"Il fait descendre avec mesure","verses":[{"n":27,"ar":"۞وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ لِعِبَادِهِۦ لَبَغَوۡاْ فِي ٱلۡأَرۡضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٖ مَّا يَشَآءُۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرُۢ بَصِيرٞ","fr":"Si Allah attribuait Ses dons avec largesse à [tous] Ses serviteurs, ils commettraient des abus sur la terre; mais, Il fait descendre avec mesure ce qu'Il veut. Il connaît parfaitement Ses serviteurs et en est Clairvoyant"}],"themes":["vie","hikma"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/42/27"},{"id":"q13-26","type":"coran","ref":"13:26","src":"Coran 13:26 · Ar-Ra'd","title":"Il étend ou restreint la subsistance","verses":[{"n":26,"ar":"ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ وَفَرِحُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا مَتَٰعٞ","fr":"Allah étend largement Ses dons ou [les] restreint à qui Il veut. Ils se réjouissent de la vie sur terre, mais la vie d'ici-bas ne paraîtra que comme une jouissance éphémère en comparaison de l'au-delà"}],"themes":["vie"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/13/26"},{"id":"q71-10-12","type":"coran","ref":"71:10-12","src":"Coran 71:10-12 · Nuh","title":"Demandez pardon : Il enverra la pluie","verses":[{"n":10,"ar":"فَقُلۡتُ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارٗا","fr":"J'ai donc dit: «Implorez le pardon de votre Seigneur, car Il est grand Pardonneur"},{"n":11,"ar":"يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا","fr":"pour qu'Il vous envoie du ciel, des pluies abondantes"},{"n":12,"ar":"وَيُمۡدِدۡكُم بِأَمۡوَٰلٖ وَبَنِينَ وَيَجۡعَل لَّكُمۡ جَنَّـٰتٖ وَيَجۡعَل لَّكُمۡ أَنۡهَٰرٗا","fr":"et qu'Il vous accorde beaucoup de biens et d'enfants, et vous donne des jardins et vous donne des rivières"}],"themes":["tawba","vie","dua"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/71/10-12"},{"id":"q31-34","type":"coran","ref":"31:34","src":"Coran 31:34 · Luqman","title":"Les cinq clés de l'invisible","verses":[{"n":34,"ar":"إِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلۡغَيۡثَ وَيَعۡلَمُ مَا فِي ٱلۡأَرۡحَامِۖ وَمَا تَدۡرِي نَفۡسٞ مَّاذَا تَكۡسِبُ غَدٗاۖ وَمَا تَدۡرِي نَفۡسُۢ بِأَيِّ أَرۡضٖ تَمُوتُۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرُۢ","fr":"La connaissance de l'Heure est auprès d'Allah; et c'est Lui qui fait tomber la pluie salvatrice; et Il sait ce qu'il y a dans les matrices. Et personne ne sait ce qu'il acquerra demain, et personne ne sait dans quelle terre il mourra. Certes, Allah est Omniscient et Parfaitement Connaisseur"}],"themes":["ghayb"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/31/34"},{"id":"q27-65","type":"coran","ref":"27:65","src":"Coran 27:65 · An-Naml","title":"Nul ne connaît l'invisible, à part Allah","verses":[{"n":65,"ar":"قُل لَّا يَعۡلَمُ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلۡغَيۡبَ إِلَّا ٱللَّهُۚ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ","fr":"Dis: «Nul de ceux qui sont dans les cieux et sur la terre ne connaît l'Inconnaissable, à part Allah». Et ils ne savent pas quand ils seront ressuscités"}],"themes":["ghayb"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/27/65"},{"id":"q7-188","type":"coran","ref":"7:188","src":"Coran 7:188 · Al-A'raf","title":"Si je connaissais l'invisible…","verses":[{"n":188,"ar":"قُل لَّآ أَمۡلِكُ لِنَفۡسِي نَفۡعٗا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُۚ وَلَوۡ كُنتُ أَعۡلَمُ ٱلۡغَيۡبَ لَٱسۡتَكۡثَرۡتُ مِنَ ٱلۡخَيۡرِ وَمَا مَسَّنِيَ ٱلسُّوٓءُۚ إِنۡ أَنَا۠ إِلَّا نَذِيرٞ وَبَشِيرٞ لِّقَوۡمٖ يُؤۡمِنُونَ","fr":"Dis: «Je ne détiens pour moi-même ni profit ni dommage, sauf ce qu'Allah veut. Et si je connaissais l'Inconnaissable, j'aurais eu des biens en abondance et aucun mal ne m'aurait touché. Je ne suis, pour les gens qui croient, qu'un avertisseur et un annonciateur»"}],"themes":["ghayb"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/7/188"},{"id":"q2-3","type":"coran","ref":"2:3","src":"Coran 2:3 · Al-Baqarah","title":"Ceux qui croient à l'invisible","verses":[{"n":3,"ar":"ٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","fr":"qui croient à l'invisible et accomplissent la Salât et dépensent (dans l'obéissance à Allah), de ce que Nous leur avons attribué"}],"themes":["ghayb"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/3"},{"id":"q39-53","type":"coran","ref":"39:53","src":"Coran 39:53 · Az-Zumar","title":"Ne désespérez pas : Allah pardonne tous les péchés","verses":[{"n":53,"ar":"۞قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ","fr":"Dis: «O Mes serviteurs qui avez commis des excès à votre propre détriment, ne désespérez pas de la miséricorde d'Allah. Car Allah pardonne tous les péchés. Oui, c'est Lui le Pardonneur, le Très Miséricordieux"}],"themes":["tawba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/39/53"},{"id":"q25-70","type":"coran","ref":"25:70","src":"Coran 25:70 · Al-Furqan","title":"Il change leurs mauvaises actions en bonnes","verses":[{"n":70,"ar":"إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلٗا صَٰلِحٗا فَأُوْلَـٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمۡ حَسَنَٰتٖۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا","fr":"sauf celui qui se repent, croit et accomplit une bonne œuvre; ceux-là Allah changera leurs mauvaises actions en bonnes, et Allah est Pardonneur et Miséricordieux"}],"themes":["tawba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/25/70"},{"id":"q3-135","type":"coran","ref":"3:135","src":"Coran 3:135 · Ali 'Imran","title":"Ils se souviennent d’Allah et demandent pardon","verses":[{"n":135,"ar":"وَٱلَّذِينَ إِذَا فَعَلُواْ فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ لِذُنُوبِهِمۡ وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ يُصِرُّواْ عَلَىٰ مَا فَعَلُواْ وَهُمۡ يَعۡلَمُونَ","fr":"et pour ceux qui, s'ils ont commis quelque turpitude ou causé quelque préjudice à leurs propres âmes (en désobéissant à Allah), se souviennent d'Allah et demandent pardon pour leurs péchés - et qui est-ce qui pardonne les péchés sinon Allah? - et qui ne persistent pas sciemment dans le mal qu'ils ont fait"}],"themes":["tawba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/3/135"},{"id":"q2-37","type":"coran","ref":"2:37","src":"Coran 2:37 · Al-Baqarah","title":"Adam reçut des paroles, et Allah accepta son repentir","verses":[{"n":37,"ar":"فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","fr":"Puis Adam reçut de son Seigneur des paroles, et Allah agréa son repentir car c'est Lui certes, le Repentant, le Miséricordieux"}],"themes":["tawba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/2/37"},{"id":"q20-121-122","type":"coran","ref":"20:121-122","src":"Coran 20:121-122 · Taha","title":"Adam désobéit, puis son Seigneur l’élut","verses":[{"n":121,"ar":"فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ","fr":"Tous deux (Adam et Eve) en mangèrent. Alors leur apparut leur nudité. Ils se mirent à se couvrir avec des feuilles du paradis. Adam désobéit ainsi à son Seigneur et il s'égara"},{"n":122,"ar":"ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ","fr":"Son Seigneur l'a ensuite élu, agréé son repentir et l'a guidé"}],"themes":["tawba"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/20/121-122"},{"id":"q14-7","type":"coran","ref":"14:7","src":"Coran 14:7 · Ibrahim","title":"Si vous êtes reconnaissants, J’augmenterai","verses":[{"n":7,"ar":"وَإِذۡ تَأَذَّنَ رَبُّكُمۡ لَئِن شَكَرۡتُمۡ لَأَزِيدَنَّكُمۡۖ وَلَئِن كَفَرۡتُمۡ إِنَّ عَذَابِي لَشَدِيدٞ","fr":"Et lorsque votre Seigneur proclama: «Si vous êtes reconnaissants, très certainement J'augmenterai [Mes bienfaits] pour vous. Mais si vous êtes ingrats, Mon châtiment sera terrible»"}],"themes":["shukr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/14/7"},{"id":"q16-53","type":"coran","ref":"16:53","src":"Coran 16:53 · An-Nahl","title":"Tout bienfait vient d'Allah","verses":[{"n":53,"ar":"وَمَا بِكُم مِّن نِّعۡمَةٖ فَمِنَ ٱللَّهِۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيۡهِ تَجۡـَٔرُونَ","fr":"Et tout ce que vous avez comme bienfait provient d'Allah. Puis quand le malheur vous touche, c'est Lui que vous implorez à haute voix"}],"themes":["shukr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/16/53"},{"id":"q27-40","type":"coran","ref":"27:40","src":"Coran 27:40 · An-Naml","title":"Salomon : « pour m’éprouver »","verses":[{"n":40,"ar":"قَالَ ٱلَّذِي عِندَهُۥ عِلۡمٞ مِّنَ ٱلۡكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن يَرۡتَدَّ إِلَيۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ","fr":"Quelqu'un qui avait une connaissance du Livre dit: «Je te l'apporterai avant que tu n'aies cligné de l'œil». Quand ensuite, Salomon a vu le trône installé auprès de lui, il dit: «Cela est de la grâce de mon Seigneur, pour m'éprouver si je suis reconnaissant ou si je suis ingrat. Quiconque est reconnaissant c'est dans son propre intérêt qu'il le fait, et quiconque est ingrat... alors mon Seigneur Se suffit à Lui-même et Il est Généreux»"}],"themes":["shukr"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/27/40"},{"id":"q28-78","type":"coran","ref":"28:78","src":"Coran 28:78 · Al-Qasas","title":"Coré : « c’est par ma science »","verses":[{"n":78,"ar":"قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمٍ عِندِيٓۚ أَوَلَمۡ يَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةٗ وَأَكۡثَرُ جَمۡعٗاۚ وَلَا يُسۡـَٔلُ عَن ذُنُوبِهِمُ ٱلۡمُجۡرِمُونَ","fr":"Il dit: «C'est par une science que je possède que ceci m'est venu». Ne savait-il pas qu'avant lui Allah avait fait périr des générations supérieures à lui en force et plus riches en biens? Et les criminels ne seront pas interrogés sur leurs péchés»"}],"themes":["shukr","excuse"],"note":"L'erreur inverse de l'excuse du destin : s'attribuer à soi seul la réussite.","grade":"Coran","level":"coran","link":"https://quran.com/28/78"},{"id":"q18-39","type":"coran","ref":"18:39","src":"Coran 18:39 · Al-Kahf","title":"« Mâ shâ’ Allâh, lâ quwwata illâ billâh »","verses":[{"n":39,"ar":"وَلَوۡلَآ إِذۡ دَخَلۡتَ جَنَّتَكَ قُلۡتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِۚ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالٗا وَوَلَدٗا","fr":"En entrant dans ton jardin, que ne dis-tu: «Telle est la volonté (et la grâce) d'Allah! Il n'y a de puissance que par Allah». Si tu me vois moins pourvu que toi en biens et en enfants"}],"themes":["shukr","mashia"],"note":"","grade":"Coran","level":"coran","link":"https://quran.com/18/39"},{"id":"h-jibril","type":"hadith","ar":"أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الآخِرِ وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ","fr":"(Jibrîl demanda : « Informe-moi sur la foi. » Le Prophète ﷺ répondit :) « Que tu croies en Allah, en Ses anges, en Ses Livres, en Ses messagers, au Jour dernier, et que tu croies au destin (al-qadar), dans son bien comme dans son mal. »","src":"Muslim 8","grade":"Sahîh — Muslim","level":"sahih","themes":["ilm","kitaba","mashia","khalq"],"title":"Le sixième pilier de la foi","note":"Le hadith de Jibrîl, rapporté par 'Umar. Croire au destin fait partie des six piliers de la foi.","link":"https://sunnah.com/muslim:8","narr":"'Umar ibn al-Khattâb"},{"id":"h-ibnumar","type":"hadith","ar":"لَوْ أَنَّ لأَحَدِهِمْ مِثْلَ أُحُدٍ ذَهَبًا فَأَنْفَقَهُ مَا قَبِلَ اللَّهُ مِنْهُ حَتَّى يُؤْمِنَ بِالْقَدَرِ","fr":"« Si l'un d'eux possédait l'équivalent du mont Uhud en or et le dépensait, Allah ne l'accepterait pas de lui tant qu'il ne croit pas au destin. »","src":"Muslim 8 (parole d’Ibn ‘Umar)","grade":"Sahîh — Muslim","level":"sahih","themes":["kitaba"],"title":"Ibn ‘Umar face aux négateurs du destin","note":"Réponse d'Ibn 'Umar à ceux qui, à Bassora, prétendaient que rien n'est décrété d'avance (la première apparition des Qadariyya).","link":"https://sunnah.com/muslim:8","narr":"Yahyâ ibn Ya'mur"},{"id":"h-50000","type":"hadith","ar":"كَتَبَ اللَّهُ مَقَادِيرَ الْخَلاَئِقِ قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالأَرْضَ بِخَمْسِينَ أَلْفَ سَنَةٍ - قَالَ - وَعَرْشُهُ عَلَى الْمَاءِ","fr":"« Allah a écrit les mesures (maqâdîr) des créatures cinquante mille ans avant de créer les cieux et la terre. » Et il dit : « Et Son Trône était sur l'eau. »","src":"Muslim 2653","grade":"Sahîh — Muslim","level":"sahih","themes":["kitaba"],"title":"Cinquante mille ans avant les cieux","note":"","link":"https://sunnah.com/muslim:2653","narr":"'Abdullâh ibn 'Amr ibn al-'Âs"},{"id":"h-qalam","type":"hadith","ar":"يَا بُنَىَّ إِنَّكَ لَنْ تَجِدَ طَعْمَ حَقِيقَةِ الإِيمَانِ حَتَّى تَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ وَمَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ إِنَّ أَوَّلَ مَا خَلَقَ اللَّهُ الْقَلَمَ فَقَالَ لَهُ اكْتُبْ. قَالَ رَبِّ وَمَاذَا أَكْتُبُ قَالَ اكْتُبْ مَقَادِيرَ كُلِّ شَىْءٍ حَتَّى تَقُومَ السَّاعَةُ","fr":"'Ubâda ibn as-Sâmit dit à son fils : « Mon fils, tu ne goûteras pas la saveur de la réalité de la foi tant que tu ne sauras pas que ce qui t'a atteint ne pouvait pas te manquer, et que ce qui t'a manqué ne pouvait pas t'atteindre. J'ai entendu le Messager d'Allah ﷺ dire : « La première chose qu'Allah a créée est la Plume. Il lui dit : Écris ! Elle dit : Seigneur, qu'écrirai-je ? Il dit : Écris les mesures de toute chose jusqu'à ce que l'Heure arrive. » »","src":"Abû Dâwûd 4700 · Tirmidhî 2155","grade":"Sahîh (al-Albânî)","level":"sahih","themes":["kitaba","sabr"],"title":"La Plume et la saveur de la foi","note":"","link":"https://sunnah.com/abudawud:4700","narr":"'Ubâda ibn as-Sâmit"},{"id":"h-masud","type":"hadith","ar":"إِنَّ أَحَدَكُمْ يُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّهِ أَرْبَعِينَ يَوْمًا، ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ، ثُمَّ يَكُونُ مُضْغَةً مِثْلَ ذَلِكَ، ثُمَّ يَبْعَثُ اللَّهُ مَلَكًا، فَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ، وَيُقَالُ لَهُ اكْتُبْ عَمَلَهُ وَرِزْقَهُ وَأَجَلَهُ وَشَقِيٌّ أَوْ سَعِيدٌ. ثُمَّ يُنْفَخُ فِيهِ الرُّوحُ، فَإِنَّ الرَّجُلَ مِنْكُمْ لَيَعْمَلُ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَ الْجَنَّةِ إِلاَّ ذِرَاعٌ، فَيَسْبِقُ عَلَيْهِ كِتَابُهُ، فَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ، وَيَعْمَلُ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَ النَّارِ إِلاَّ ذِرَاعٌ، فَيَسْبِقُ عَلَيْهِ الْكِتَابُ، فَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ","fr":"« La création de chacun de vous est rassemblée dans le ventre de sa mère quarante jours, puis il devient une adhérence ('alaqa) pendant autant, puis un morceau de chair (mudgha) pendant autant. Puis Allah envoie un ange qui reçoit l'ordre de quatre mots ; on lui dit : écris ses œuvres, sa subsistance, son terme, et s'il sera malheureux ou heureux. Puis on lui insuffle l'âme. Et l'homme parmi vous œuvre jusqu'à ce qu'il n'y ait plus entre lui et le Paradis qu'une coudée ; alors son écrit le devance et il fait les œuvres des gens de l'Enfer. Et il œuvre jusqu'à ce qu'il n'y ait plus entre lui et l'Enfer qu'une coudée ; alors l'écrit le devance et il fait les œuvres des gens du Paradis. »","src":"Bukhârî 3208 · Muslim 2643","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["kitaba","vie"],"title":"Les quatre choses écrites dans le ventre de la mère","note":"L'autre version (hadith suivant) précise : il faisait ces œuvres « en ce qui paraît aux gens ». Allah ne laisse pas tomber un cœur sincère au dernier moment.","link":"https://sunnah.com/bukhari:3208","narr":"'Abdullâh ibn Mas'ûd"},{"id":"h-apparence","type":"hadith","ar":"إِنَّ الرَّجُلَ لَيَعْمَلُ عَمَلَ أَهْلِ الْجَنَّةِ فِيمَا يَبْدُو لِلنَّاسِ، وَهْوَ مِنْ أَهْلِ النَّارِ، وَإِنَّ الرَّجُلَ لَيَعْمَلُ عَمَلَ أَهْلِ النَّارِ فِيمَا يَبْدُو لِلنَّاسِ، وَهْوَ مِنْ أَهْلِ الْجَنَّةِ … وَإِنَّمَا الأَعْمَالُ بِالْخَوَاتِيمِ","fr":"« L'homme fait les œuvres des gens du Paradis, en ce qui paraît aux gens, alors qu'il est des gens de l'Enfer ; et l'homme fait les œuvres des gens de l'Enfer, en ce qui paraît aux gens, alors qu'il est des gens du Paradis. » … « Les œuvres ne valent que par leurs fins. »","src":"Bukhârî 2898 · 6607 · Muslim 112","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["kitaba","choix"],"title":"Les œuvres valent par leurs fins","note":"Prononcé au sujet d'un combattant admiré de tous, qui finit par se donner la mort. Ce qui compte est l'état réel du cœur et la fin de la vie : d'où la crainte et l'espoir.","link":"https://sunnah.com/bukhari:2898","narr":"Sahl ibn Sa'd as-Sâ'idî"},{"id":"h-ali","type":"hadith","ar":"مَا مِنْكُمْ مِنْ أَحَدٍ إِلاَّ وَقَدْ كُتِبَ مَقْعَدُهُ مِنَ النَّارِ وَمَقْعَدُهُ مِنَ الْجَنَّةِ. قَالُوا يَا رَسُولَ اللَّهِ أَفَلاَ نَتَّكِلُ عَلَى كِتَابِنَا وَنَدَعُ الْعَمَلَ قَالَ اعْمَلُوا فَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ، أَمَّا مَنْ كَانَ مِنْ أَهْلِ السَّعَادَةِ فَيُيَسَّرُ لِعَمَلِ أَهْلِ السَّعَادَةِ، وَأَمَّا مَنْ كَانَ مِنْ أَهْلِ الشَّقَاءِ فَيُيَسَّرُ لِعَمَلِ أَهْلِ الشَّقَاوَةِ","fr":"« Il n'est aucun d'entre vous dont la place en Enfer et la place au Paradis n'aient été écrites. » Ils dirent : « Ô Messager d'Allah, ne nous en remettrons-nous pas à ce qui est écrit pour nous, en délaissant les œuvres ? » Il dit : « Œuvrez ! Chacun se voit faciliter ce pour quoi il a été créé. Celui qui est des gens du bonheur se voit faciliter les œuvres des gens du bonheur, et celui qui est des gens du malheur se voit faciliter les œuvres des gens du malheur. » Puis il récita : « Celui qui donne et craint Allah… » (92:5-10).","src":"Bukhârî 4949 · Muslim 2647","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["kitaba","choix","effort","excuse"],"title":"« Œuvrez, chacun se voit faciliter »","note":"La réponse exacte à la question « si tout est écrit, pourquoi agir ? » : l'écrit est caché, l'ordre d'agir est clair.","link":"https://sunnah.com/bukhari:4949","narr":"'Alî ibn Abî Tâlib"},{"id":"h-suraqa","type":"hadith","ar":"يَا رَسُولَ اللَّهِ بَيِّنْ لَنَا دِينَنَا كَأَنَّا خُلِقْنَا الآنَ فِيمَا الْعَمَلُ الْيَوْمَ أَفِيمَا جَفَّتْ بِهِ الأَقْلاَمُ وَجَرَتْ بِهِ الْمَقَادِيرُ أَمْ فِيمَا نَسْتَقْبِلُ قَالَ لاَ. بَلْ فِيمَا جَفَّتْ بِهِ الأَقْلاَمُ وَجَرَتْ بِهِ الْمَقَادِيرُ. قَالَ فَفِيمَ الْعَمَلُ قَالَ زُهَيْرٌ ثُمَّ تَكَلَّمَ أَبُو الزُّبَيْرِ بِشَىْءٍ لَمْ أَفْهَمْهُ فَسَأَلْتُ مَا قَالَ فَقَالَ اعْمَلُوا فَكُلٌّ مُيَسَّرٌ","fr":"Surâqa ibn Mâlik dit : « Ô Messager d'Allah, explique-nous notre religion comme si nous venions d'être créés : les œuvres d'aujourd'hui sont-elles dans ce sur quoi les plumes ont séché et les décrets ont couru, ou dans ce que nous allons accueillir ? » Il dit : « Non, dans ce sur quoi les plumes ont séché et les décrets ont couru. » Il dit : « Alors à quoi bon œuvrer ? » Il dit : « Œuvrez, car chacun se voit faciliter (sa voie). »","src":"Muslim 2648","grade":"Sahîh — Muslim","level":"sahih","themes":["kitaba","choix","effort"],"title":"Surâqa : « Alors à quoi bon œuvrer ? »","note":"","link":"https://sunnah.com/muslim:2648","narr":"Jâbir ibn 'Abdillâh"},{"id":"h-imran","type":"hadith","ar":"أَيُعْرَفُ أَهْلُ الْجَنَّةِ مِنْ أَهْلِ النَّارِ قَالَ نَعَمْ. قَالَ فَلِمَ يَعْمَلُ الْعَامِلُونَ قَالَ كُلٌّ يَعْمَلُ لِمَا خُلِقَ لَهُ ـ أَوْ لِمَا يُسِّرَ لَهُ","fr":"Un homme dit : « Ô Messager d'Allah, les gens du Paradis sont-ils connus d'avance parmi les gens de l'Enfer ? » Il dit : « Oui. » Il dit : « Alors pourquoi ceux qui œuvrent œuvrent-ils ? » Il dit : « Chacun œuvre pour ce pour quoi il a été créé — ou : pour ce qui lui a été facilité. »","src":"Bukhârî 6596","grade":"Sahîh — Bukhârî","level":"sahih","themes":["ilm","choix"],"title":"Pourquoi ceux qui œuvrent œuvrent-ils ?","note":"","link":"https://sunnah.com/bukhari:6596","narr":"'Imrân ibn Husayn"},{"id":"h-ajz","type":"hadith","ar":"كُلُّ شَىْءٍ بِقَدَرٍ حَتَّى الْعَجْزُ وَالْكَيْسُ أَوِ الْكَيْسُ وَالْعَجْزُ","fr":"« Toute chose est selon un décret, même l'incapacité et l'habileté — ou : l'habileté et l'incapacité. »","src":"Muslim 2656","grade":"Sahîh — Muslim","level":"sahih","themes":["mashia","khalq"],"title":"Même l'incapacité et l'habileté","note":"Tâwûs rapporte avoir connu des Compagnons qui disaient tous : « Toute chose est selon un décret. »","link":"https://sunnah.com/muslim:2656","narr":"'Abdullâh ibn 'Umar"},{"id":"h-coeurs","type":"hadith","ar":"إِنَّ قُلُوبَ بَنِي آدَمَ كُلَّهَا بَيْنَ إِصْبَعَيْنِ مِنْ أَصَابِعِ الرَّحْمَنِ كَقَلْبٍ وَاحِدٍ يُصَرِّفُهُ حَيْثُ يَشَاءُ. ثُمَّ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم اللَّهُمَّ مُصَرِّفَ الْقُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ","fr":"« Les cœurs des fils d'Adam sont tous entre deux doigts parmi les doigts du Tout-Miséricordieux, comme un seul cœur : Il le tourne comme Il veut. » Puis le Messager d'Allah ﷺ dit : « Ô Allah, Toi qui tournes les cœurs, tourne nos cœurs vers Ton obéissance. »","src":"Muslim 2655","grade":"Sahîh — Muslim","level":"sahih","themes":["hidaya","mashia","dua"],"title":"Les cœurs entre deux doigts du Tout-Miséricordieux","note":"","link":"https://sunnah.com/muslim:2655","narr":"'Abdullâh ibn 'Amr"},{"id":"h-muqallib","type":"hadith","ar":"يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ. فَقُلْتُ يَا رَسُولَ اللَّهِ آمَنَّا بِكَ وَبِمَا جِئْتَ بِهِ فَهَلْ تَخَافُ عَلَيْنَا قَالَ نَعَمْ إِنَّ الْقُلُوبَ بَيْنَ أَصْبُعَيْنِ مِنْ أَصَابِعِ اللَّهِ يُقَلِّبُهَا كَيْفَ يَشَاءُ","fr":"Le Messager d'Allah ﷺ disait souvent : « Ô Toi qui retournes les cœurs, affermis mon cœur sur Ta religion. » Je dis : « Ô Messager d'Allah, nous avons cru en toi et en ce que tu as apporté : crains-tu pour nous ? » Il dit : « Oui. Les cœurs sont entre deux doigts parmi les doigts d'Allah, Il les retourne comme Il veut. »","src":"Tirmidhî 2140","grade":"Hasan (Tirmidhî) · Sahîh (al-Albânî)","level":"sahih","themes":["hidaya","dua"],"title":"« Affermis mon cœur sur Ta religion »","note":"","link":"https://sunnah.com/tirmidhi:2140","narr":"Anas ibn Mâlik"},{"id":"h-ihfaz","type":"hadith","ar":"يَا غُلاَمُ إِنِّي أُعَلِّمُكَ كَلِمَاتٍ احْفَظِ اللَّهَ يَحْفَظْكَ احْفَظِ اللَّهَ تَجِدْهُ تُجَاهَكَ إِذَا سَأَلْتَ فَاسْأَلِ اللَّهَ وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللَّهِ وَاعْلَمْ أَنَّ الأُمَّةَ لَوِ اجْتَمَعَتْ عَلَى أَنْ يَنْفَعُوكَ بِشَيْءٍ لَمْ يَنْفَعُوكَ إِلاَّ بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ لَكَ وَلَوِ اجْتَمَعُوا عَلَى أَنْ يَضُرُّوكَ بِشَيْءٍ لَمْ يَضُرُّوكَ إِلاَّ بِشَيْءٍ قَدْ كَتَبَهُ اللَّهُ عَلَيْكَ رُفِعَتِ الأَقْلاَمُ وَجَفَّتِ الصُّحُفُ","fr":"« Ô jeune garçon, je vais t'apprendre des paroles : préserve Allah, Il te préservera ; préserve Allah, tu Le trouveras devant toi. Si tu demandes, demande à Allah ; si tu cherches de l'aide, cherche-la auprès d'Allah. Et sache que si la communauté entière se rassemblait pour te faire profiter de quelque chose, elle ne te ferait profiter que de ce qu'Allah a déjà écrit pour toi ; et si elle se rassemblait pour te nuire, elle ne te nuirait que par ce qu'Allah a déjà écrit contre toi. Les plumes ont été levées et les feuilles ont séché. »","src":"Tirmidhî 2516","grade":"Hasan sahîh (Tirmidhî)","level":"sahih","themes":["kitaba","tawakkul","dua"],"title":"« Préserve Allah, Il te préservera »","note":"","link":"https://sunnah.com/tirmidhi:2516","narr":"'Abdullâh ibn 'Abbâs"},{"id":"h-ihfaz2","type":"hadith","ar":"وَاعْلَمْ أَنَّ النَّصْرَ مَعَ الصَّبْرِ، وَأَنْ الْفَرَجَ مَعَ الْكَرْبِ، وَأَنَّ مَعَ الْعُسْرِ يُسْرًا","fr":"« … Et sache que la victoire vient avec la patience, que la délivrance vient avec l'angoisse, et qu'avec la difficulté vient une facilité. »","src":"Ahmad · an-Nawawî, 40 hadiths n°19","grade":"Version longue, retenue par an-Nawawî","level":"hasan","themes":["sabr"],"title":"La victoire vient avec la patience","note":"Fin de la version longue du hadith d'Ibn 'Abbâs (« Préserve Allah… »), rapportée par Ahmad et citée par an-Nawawî.","link":"","narr":"'Abdullâh ibn 'Abbâs"},{"id":"h-fort","type":"hadith","ar":"الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللَّهِ مِنَ الْمُؤْمِنِ الضَّعِيفِ وَفِي كُلٍّ خَيْرٌ احْرِصْ عَلَى مَا يَنْفَعُكَ وَاسْتَعِنْ بِاللَّهِ وَلاَ تَعْجِزْ وَإِنْ أَصَابَكَ شَىْءٌ فَلاَ تَقُلْ لَوْ أَنِّي فَعَلْتُ كَانَ كَذَا وَكَذَا. وَلَكِنْ قُلْ قَدَرُ اللَّهِ وَمَا شَاءَ فَعَلَ فَإِنَّ لَوْ تَفْتَحُ عَمَلَ الشَّيْطَانِ","fr":"« Le croyant fort est meilleur et plus aimé d'Allah que le croyant faible, et en chacun il y a du bien. Recherche avec ardeur ce qui t'est profitable, demande l'aide d'Allah, et ne baisse pas les bras. Et si quelque chose t'atteint, ne dis pas : « Si j'avais fait ceci, il en aurait été ainsi et ainsi », mais dis : « Allah l'a décrété, et ce qu'Il a voulu, Il l'a fait » (qaddara Allâhu wa mâ shâ'a fa'al), car le « si » ouvre la porte à l'œuvre du Shaytân. »","src":"Muslim 2664","grade":"Sahîh — Muslim","level":"sahih","themes":["effort","tawakkul","sabr","excuse"],"title":"Le croyant fort : avant, pendant, après","note":"Le plan complet en une phrase : avant l'événement, effort + demande d'aide + persévérance ; après l'événement, acceptation sans « si seulement ».","link":"https://sunnah.com/muslim:2664","narr":"Abû Hurayra"},{"id":"h-ajaban","type":"hadith","ar":"عَجَبًا لأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ وَلَيْسَ ذَاكَ لأَحَدٍ إِلاَّ لِلْمُؤْمِنِ إِنْ أَصَابَتْهُ سَرَّاءُ شَكَرَ فَكَانَ خَيْرًا لَهُ وَإِنْ أَصَابَتْهُ ضَرَّاءُ صَبَرَ فَكَانَ خَيْرًا لَهُ","fr":"« Que l'affaire du croyant est étonnante ! Toute son affaire est un bien, et cela n'appartient qu'au croyant : si un bonheur l'atteint, il remercie, et c'est un bien pour lui ; si un malheur l'atteint, il patiente, et c'est un bien pour lui. »","src":"Muslim 2999","grade":"Sahîh — Muslim","level":"sahih","themes":["sabr","shukr"],"title":"Que l'affaire du croyant est étonnante !","note":"","link":"https://sunnah.com/muslim:2999","narr":"Suhayb ar-Rûmî"},{"id":"h-jabir","type":"hadith","ar":"لاَ يُؤْمِنُ عَبْدٌ حَتَّى يُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ حَتَّى يَعْلَمَ أَنَّ مَا أَصَابَهُ لَمْ يَكُنْ لِيُخْطِئَهُ وَأَنَّ مَا أَخْطَأَهُ لَمْ يَكُنْ لِيُصِيبَهُ","fr":"« Le serviteur ne croit pas (vraiment) tant qu'il ne croit pas au destin, dans son bien et dans son mal, au point de savoir que ce qui l'a atteint ne pouvait pas le manquer, et que ce qui l'a manqué ne pouvait pas l'atteindre. »","src":"Tirmidhî 2144","grade":"Hasan","level":"hasan","themes":["kitaba","sabr"],"title":"Ce qui t’a atteint ne pouvait pas te manquer","note":"","link":"https://sunnah.com/tirmidhi:2144","narr":"Jâbir ibn 'Abdillâh"},{"id":"h-adam","type":"hadith","ar":"احْتَجَّ آدَمُ وَمُوسَى، فَقَالَ لَهُ مُوسَى يَا آدَمُ أَنْتَ أَبُونَا خَيَّبْتَنَا وَأَخْرَجْتَنَا مِنَ الْجَنَّةِ. قَالَ لَهُ آدَمُ يَا مُوسَى اصْطَفَاكَ اللَّهُ بِكَلاَمِهِ، وَخَطَّ لَكَ بِيَدِهِ، أَتَلُومُنِي عَلَى أَمْرٍ قَدَّرَ اللَّهُ عَلَىَّ قَبْلَ أَنْ يَخْلُقَنِي بِأَرْبَعِينَ سَنَةً. فَحَجَّ آدَمُ مُوسَى","fr":"« Adam et Moïse se disputèrent. Moïse lui dit : « Ô Adam, tu es notre père : tu nous as déçus et tu nous as fait sortir du Paradis. » Adam lui dit : « Ô Moïse, Allah t'a choisi par Sa parole et t'a écrit (la Torah) de Sa main : me blâmes-tu pour une chose qu'Allah a décrétée pour moi quarante ans avant de me créer ? » Et Adam l'emporta sur Moïse. »","src":"Bukhârî 6614 · Muslim 2652","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["excuse","tawba"],"title":"Adam et Moïse","note":"Adam s'était repenti et Allah lui avait pardonné (2:37 ; 20:122). Moïse lui reprochait la conséquence, la sortie du Paradis, qui est un malheur. Adam invoque donc le destin pour un malheur, pas pour excuser un péché. D'où la règle : « on invoque le destin face aux malheurs, pas pour les fautes ».","link":"https://sunnah.com/bukhari:6614","narr":"Abû Hurayra"},{"id":"h-alifatima","type":"hadith","ar":"أَلاَ تُصَلِّيَانِ. فَقُلْتُ يَا رَسُولَ اللَّهِ، أَنْفُسُنَا بِيَدِ اللَّهِ، فَإِذَا شَاءَ أَنْ يَبْعَثَنَا بَعَثَنَا. فَانْصَرَفَ حِينَ قُلْنَا ذَلِكَ وَلَمْ يَرْجِعْ إِلَىَّ شَيْئًا. ثُمَّ سَمِعْتُهُ وَهْوَ مُوَلٍّ يَضْرِبُ فَخِذَهُ وَهْوَ يَقُولُ وَكَانَ الإِنْسَانُ أَكْثَرَ شَىْءٍ جَدَلاً","fr":"Le Messager d'Allah ﷺ vint une nuit chez 'Alî et Fâtima et dit : « Ne priez-vous pas ? » 'Alî dit : « Ô Messager d'Allah, nos âmes sont dans la main d'Allah ; s'Il veut nous réveiller, Il nous réveille. » Il s'en alla sans rien me répondre, puis je l'entendis, tournant le dos, se frapper la cuisse en disant : « L'homme est, de tous les êtres, le plus grand disputeur » (18:54).","src":"Bukhârî 1127 · Muslim 775","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["excuse"],"title":"« Nos âmes sont dans la main d'Allah »","note":"La parole de 'Alî est vraie en soi, mais elle ne peut pas servir à délaisser une œuvre : le Prophète ﷺ la qualifie de dispute.","link":"https://sunnah.com/bukhari:1127","narr":"'Alî ibn Abî Tâlib"},{"id":"h-peste","type":"hadith","ar":"أَفِرَارًا مِنْ قَدَرِ اللَّهِ فَقَالَ عُمَرُ لَوْ غَيْرُكَ قَالَهَا يَا أَبَا عُبَيْدَةَ، نَعَمْ نَفِرُّ مِنْ قَدَرِ اللَّهِ إِلَى قَدَرِ اللَّهِ، أَرَأَيْتَ لَوْ كَانَ لَكَ إِبِلٌ هَبَطَتْ وَادِيًا لَهُ عُدْوَتَانِ، إِحْدَاهُمَا خَصِبَةٌ، وَالأُخْرَى جَدْبَةٌ، أَلَيْسَ إِنْ رَعَيْتَ الْخَصْبَةَ رَعَيْتَهَا بِقَدَرِ اللَّهِ","fr":"(Apprenant qu'une épidémie frappait le Shâm, 'Umar consulta puis décida de rebrousser chemin.) Abû 'Ubayda dit : « Est-ce une fuite devant le décret d'Allah ? » 'Umar dit : « Si seulement un autre que toi l'avait dit, ô Abû 'Ubayda ! Oui, nous fuyons le décret d'Allah vers le décret d'Allah. Vois-tu, si tu avais des chameaux descendus dans une vallée à deux versants, l'un fertile et l'autre aride : si tu les fais paître sur le fertile, n'est-ce pas par le décret d'Allah ? (Et si tu les fais paître sur l'aride, n'est-ce pas par le décret d'Allah ?) »","src":"Bukhârî 5729 · Muslim 2219","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["effort","excuse","tawakkul"],"title":"Fuir le décret d’Allah vers le décret d’Allah","note":"'Abd ar-Rahmân ibn 'Awf arriva ensuite et confirma par un hadith du Prophète ﷺ : ne pas entrer dans une terre touchée par l'épidémie. Prendre une précaution, c'est passer d'un décret à un autre décret.","link":"https://sunnah.com/bukhari:5729","narr":"'Abdullâh ibn 'Abbâs"},{"id":"h-chamelle","type":"hadith","ar":"يَا رَسُولَ اللَّهِ أَعْقِلُهَا وَأَتَوَكَّلُ أَوْ أُطْلِقُهَا وَأَتَوَكَّلُ قَالَ اعْقِلْهَا وَتَوَكَّلْ","fr":"Un homme dit : « Ô Messager d'Allah, dois-je l'attacher (ma chamelle) et placer ma confiance en Allah, ou la laisser libre et placer ma confiance ? » Il dit : « Attache-la, et place ta confiance. »","src":"Tirmidhî 2517","grade":"Hasan (al-Albânî)","level":"hasan","themes":["tawakkul","effort"],"title":"« Attache-la, et place ta confiance »","note":"","link":"https://sunnah.com/tirmidhi:2517","narr":"Anas ibn Mâlik"},{"id":"h-oiseaux","type":"hadith","ar":"لَوْ أَنَّكُمْ كُنْتُمْ تَوَكَّلُونَ عَلَى اللَّهِ حَقَّ تَوَكُّلِهِ لَرُزِقْتُمْ كَمَا تُرْزَقُ الطَّيْرُ تَغْدُو خِمَاصًا وَتَرُوحُ بِطَانًا","fr":"« Si vous placiez votre confiance en Allah comme il se doit, Il vous accorderait votre subsistance comme Il l'accorde aux oiseaux : ils partent le matin le ventre vide et reviennent le soir rassasiés. »","src":"Tirmidhî 2344 · Ibn Mâjah 4164","grade":"Hasan sahîh (Tirmidhî)","level":"sahih","themes":["tawakkul","effort","vie"],"title":"Comme les oiseaux","note":"Les oiseaux ne restent pas au nid : ils sortent chercher. La vraie confiance accompagne l'effort.","link":"https://sunnah.com/tirmidhi:2344","narr":"'Umar ibn al-Khattâb"},{"id":"h-dirayn","type":"hadith","ar":"ظَاهَرَ يَوْمَ أُحُدٍ بَيْنَ دِرْعَيْنِ","fr":"(Le Prophète ﷺ) porta, le jour de Uhud, deux cottes de mailles l'une sur l'autre.","src":"Abû Dâwûd 2590 · Ibn Mâjah 2806","grade":"Sahîh (al-Albânî)","level":"sahih","themes":["effort","tawakkul"],"title":"Deux cottes de mailles à Uhud","note":"Le meilleur de ceux qui placent leur confiance en Allah prenait aussi les meilleures précautions.","link":"https://sunnah.com/abudawud:2590","narr":"as-Sâ'ib ibn Yazîd"},{"id":"h-70000","type":"hadith","ar":"يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ، هُمُ الَّذِينَ لاَ يَسْتَرْقُونَ، وَلاَ يَتَطَيَّرُونَ، وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ","fr":"« Soixante-dix mille de ma communauté entreront au Paradis sans jugement : ce sont ceux qui ne demandent pas qu'on leur fasse la ruqya, qui ne tirent pas de présages, et qui placent leur confiance en leur Seigneur. »","src":"Bukhârî 6472 · 5705","grade":"Sahîh — Bukhârî","level":"sahih","themes":["tawakkul"],"title":"Les soixante-dix mille","note":"Le hadith ne condamne pas les remèdes : le Prophète ﷺ s'est soigné et a ordonné de se soigner. Il loue un cœur qui ne dépend de rien d'autre qu'Allah.","link":"https://sunnah.com/bukhari:6472","narr":"'Abdullâh ibn 'Abbâs"},{"id":"h-remede","type":"hadith","ar":"مَا أَنْزَلَ اللَّهُ دَاءً إِلاَّ أَنْزَلَ لَهُ شِفَاءً … لِكُلِّ دَاءٍ دَوَاءٌ فَإِذَا أُصِيبَ دَوَاءُ الدَّاءِ بَرَأَ بِإِذْنِ اللَّهِ عَزَّ وَجَلَّ","fr":"« Allah n'a fait descendre aucune maladie sans faire descendre pour elle un remède. » … « Pour chaque maladie il y a un remède : quand le remède atteint la maladie, elle guérit par la permission d'Allah, Puissant et Majestueux. »","src":"Bukhârî 5678 · Muslim 2204","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["effort","vie"],"title":"Chaque maladie a son remède","note":"","link":"https://sunnah.com/bukhari:5678","narr":"Abû Hurayra · Jâbir"},{"id":"h-qada-dua","type":"hadith","ar":"لاَ يَرُدُّ الْقَضَاءَ إِلاَّ الدُّعَاءُ وَلاَ يَزِيدُ فِي الْعُمُرِ إِلاَّ الْبِرُّ","fr":"« Rien ne repousse le décret (al-qadâ') si ce n'est l'invocation, et rien n'allonge la vie si ce n'est la bonté (al-birr). »","src":"Tirmidhî 2139","grade":"Discuté : hasan (al-Albânî), faible (Darussalam)","level":"discute","themes":["dua","kitaba"],"title":"Rien ne repousse le décret, sauf l'invocation","note":"Hadith dont l'authenticité est discutée. Son sens est appuyé par des textes sûrs : les liens de parenté (Bukhârî 5986) et les trois issues de l'invocation (al-Adab al-Mufrad 710).","link":"https://sunnah.com/tirmidhi:2139","narr":"Salmân al-Fârisî"},{"id":"h-rahm","type":"hadith","ar":"مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَيُنْسَأَ لَهُ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ","fr":"« Que celui qui aime que sa subsistance soit élargie et que sa vie soit prolongée entretienne les liens de parenté. »","src":"Bukhârî 5986 · Muslim 2557","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["dua","vie","kitaba","effort"],"title":"Les liens de parenté et la vie prolongée","note":"Les œuvres sont des causes réelles que le décret lui-même a prévues.","link":"https://sunnah.com/bukhari:5986","narr":"Anas ibn Mâlik"},{"id":"h-trois","type":"hadith","ar":"مَا مِنْ مُسْلِمٍ يَدْعُو، لَيْسَ بِإِثْمٍ وَلاَ بِقَطِيعَةِ رَحِمٍ، إِلاَّ أَعْطَاهُ إِحْدَى ثَلاَثٍ: إِمَّا أَنْ يُعَجِّلَ لَهُ دَعْوَتَهُ، وَإِمَّا أَنْ يَدَّخِرَهَا لَهُ فِي الْآخِرَةِ، وَإِمَّا أَنْ يَدْفَعَ عَنْهُ مِنَ السُّوءِ مِثْلَهَا، قَالَ: إِذًا نُكْثِرُ، قَالَ: اللَّهُ أَكْثَرُ","fr":"« Il n'est pas de musulman qui fasse une invocation ne contenant ni péché ni rupture des liens de parenté sans qu'Allah ne lui accorde l'une de trois choses : soit Il exauce rapidement son invocation, soit Il la lui garde en réserve pour l'au-delà, soit Il écarte de lui un mal équivalent. » Ils dirent : « Alors nous en ferons beaucoup. » Il dit : « Allah est plus (généreux) encore. »","src":"al-Adab al-Mufrad 710 · Ahmad","grade":"Sahîh (al-Albânî)","level":"sahih","themes":["dua"],"title":"Les trois issues de toute invocation","note":"","link":"https://sunnah.com/adab:710","narr":"Abû Sa'îd al-Khudrî"},{"id":"h-dua-ibada","type":"hadith","ar":"الدُّعَاءُ هُوَ الْعِبَادَةُ","fr":"« L'invocation, c'est l'adoration. » (Puis il récita : « Et votre Seigneur dit : Appelez-Moi, Je vous répondrai… » 40:60.)","src":"Abû Dâwûd 1479 · Tirmidhî 2969","grade":"Sahîh","level":"sahih","themes":["dua"],"title":"L'invocation, c'est l'adoration","note":"","link":"https://sunnah.com/abudawud:1479","narr":"an-Nu'mân ibn Bashîr"},{"id":"h-azm","type":"hadith","ar":"لاَ يَقُلْ أَحَدُكُمُ اللَّهُمَّ اغْفِرْ لِي إِنْ شِئْتَ، ارْحَمْنِي إِنْ شِئْتَ، ارْزُقْنِي إِنْ شِئْتَ، وَلْيَعْزِمْ مَسْأَلَتَهُ، إِنَّهُ يَفْعَلُ مَا يَشَاءُ، لاَ مُكْرِهَ لَهُ","fr":"« Que nul d'entre vous ne dise : « Ô Allah, pardonne-moi si Tu veux, fais-moi miséricorde si Tu veux, accorde-moi ma subsistance si Tu veux. » Qu'il soit résolu dans sa demande : Il fait ce qu'Il veut, nul ne Le contraint. »","src":"Bukhârî 7477 · Muslim 2679","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["dua","mashia"],"title":"Invoquer avec résolution","note":"","link":"https://sunnah.com/bukhari:7477","narr":"Abû Hurayra"},{"id":"h-hate","type":"hadith","ar":"يُسْتَجَابُ لأَحَدِكُمْ مَا لَمْ يَعْجَلْ يَقُولُ دَعَوْتُ فَلَمْ يُسْتَجَبْ لِي","fr":"« Il est répondu à chacun de vous tant qu'il ne se précipite pas en disant : « J'ai invoqué, et il ne m'a pas été répondu. » »","src":"Bukhârî 6340 · Muslim 2735","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["dua","sabr"],"title":"Ne pas se précipiter","note":"","link":"https://sunnah.com/bukhari:6340","narr":"Abû Hurayra"},{"id":"h-qunut","type":"hadith","ar":"اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ وَعَافِنِي فِيمَنْ عَافَيْتَ وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِي شَرَّ مَا قَضَيْتَ","fr":"« Ô Allah, guide-moi parmi ceux que Tu as guidés, accorde-moi la santé parmi ceux à qui Tu l'as accordée, prends-moi sous Ta protection parmi ceux que Tu as pris sous Ta protection, bénis pour moi ce que Tu m'as donné, et préserve-moi du mal de ce que Tu as décrété… »","src":"Abû Dâwûd 1425 · Tirmidhî 464 · Nasâ’î 1745","grade":"Sahîh (al-Albânî)","level":"sahih","themes":["dua","hidaya"],"title":"« Préserve-moi du mal de ce que Tu as décrété »","note":"Invocation enseignée par le Prophète ﷺ à al-Hasan ibn 'Alî (le qunût du witr). On demande à Allah de nous préserver du mal contenu dans un décret.","link":"https://sunnah.com/abudawud:1425","narr":"al-Hasan ibn 'Alî"},{"id":"h-suqada","type":"hadith","ar":"يَتَعَوَّذُ مِنْ جَهْدِ الْبَلاَءِ، وَدَرَكِ الشَّقَاءِ، وَسُوءِ الْقَضَاءِ، وَشَمَاتَةِ الأَعْدَاءِ","fr":"Le Messager d'Allah ﷺ cherchait refuge auprès d'Allah contre l'épreuve accablante, contre l'atteinte du malheur, contre le mauvais décret, et contre la joie maligne des ennemis.","src":"Bukhârî 6347 · Muslim 2707","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["dua"],"title":"Chercher refuge contre le mauvais décret","note":"","link":"https://sunnah.com/bukhari:6347","narr":"Abû Hurayra"},{"id":"h-istikhara","type":"hadith","ar":"اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلاَ أَقْدِرُ وَتَعْلَمُ وَلاَ أَعْلَمُ وَأَنْتَ عَلاَّمُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي ـ أَوْ قَالَ عَاجِلِ أَمْرِي وَآجِلِهِ ـ فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي ـ أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ ـ فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي بِهِ","fr":"« Ô Allah, je Te demande de choisir pour moi par Ta science, je Te demande de m'en rendre capable par Ta puissance, et je Te demande de Ta grâce immense. Car Tu peux et je ne peux pas, Tu sais et je ne sais pas, et Tu es Celui qui connaît parfaitement l'invisible. Ô Allah, si Tu sais que cette affaire est un bien pour moi dans ma religion, ma vie et l'issue de mon affaire, décrète-la pour moi, facilite-la-moi, puis bénis-la pour moi. Et si Tu sais que cette affaire est un mal pour moi dans ma religion, ma vie et l'issue de mon affaire, écarte-la de moi et écarte-moi d'elle, et décrète pour moi le bien où qu'il soit, puis rends-moi satisfait de lui. »","src":"Bukhârî 1166 · 6382","grade":"Sahîh — Bukhârî","level":"sahih","themes":["dua","tawakkul","effort"],"title":"La prière de consultation (istikhâra)","note":"Le Prophète ﷺ l'enseignait « comme une sourate du Coran », pour toute affaire, après deux unités de prière surérogatoire. On y voit tout le qadar : Sa science, Sa puissance, Son décret… et ta décision.","link":"https://sunnah.com/bukhari:1166","narr":"Jâbir ibn 'Abdillâh"},{"id":"h-hawqala","type":"hadith","ar":"يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ قُلْ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ فَإِنَّهَا. كَنْزٌ مِنْ كُنُوزِ الْجَنَّةِ","fr":"« Ô 'Abdallâh ibn Qays, dis : lâ hawla wa lâ quwwata illâ billâh (il n'y a de changement ni de force que par Allah), car c'est un trésor parmi les trésors du Paradis. »","src":"Bukhârî 6384 · Muslim 2704","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["tawakkul","khalq"],"title":"Un trésor du Paradis","note":"Toute force que tu utilises pour obéir ou pour éviter le mal t'est donnée par Allah.","link":"https://sunnah.com/bukhari:6384","narr":"Abû Mûsâ al-Ash'arî"},{"id":"h-ibadi","type":"hadith","ar":"يَا عِبَادِي إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا فَلاَ تَظَالَمُوا … يَا عِبَادِي كُلُّكُمْ ضَالٌّ إِلاَّ مَنْ هَدَيْتُهُ فَاسْتَهْدُونِي أَهْدِكُمْ … يَا عِبَادِي إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ ثُمَّ أُوَفِّيكُمْ إِيَّاهَا فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدِ اللَّهَ وَمَنْ وَجَدَ غَيْرَ ذَلِكَ فَلاَ يَلُومَنَّ إِلاَّ نَفْسَهُ","fr":"(Allah dit :) « Ô Mes serviteurs, Je Me suis interdit l'injustice et Je l'ai rendue interdite entre vous : ne soyez donc pas injustes les uns envers les autres. » … « Ô Mes serviteurs, vous êtes tous égarés, sauf celui que J'ai guidé : demandez-Moi donc la guidée, Je vous guiderai. » … « Ô Mes serviteurs, ce ne sont que vos œuvres que Je dénombre pour vous, puis Je vous les rétribue pleinement. Que celui qui trouve un bien loue Allah, et que celui qui trouve autre chose ne blâme que lui-même. »","src":"Muslim 2577 (hadith qudsî)","grade":"Sahîh — Muslim","level":"sahih","themes":["justice","hidaya","choix"],"title":"« Ce ne sont que vos œuvres »","note":"Le bien trouvé est une grâce d'Allah ; le mal trouvé est le fruit de nos œuvres. Les deux faces du qadar en une phrase.","link":"https://sunnah.com/muslim:2577","narr":"Abû Dharr al-Ghifârî"},{"id":"h-niyya","type":"hadith","ar":"إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى","fr":"« Les actes ne valent que par les intentions, et chacun n'aura que ce qu'il a eu l'intention de faire. »","src":"Bukhârî 1 · Muslim 1907","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["choix"],"title":"Les actes ne valent que par les intentions","note":"","link":"https://sunnah.com/bukhari:1","narr":"'Umar ibn al-Khattâb"},{"id":"h-pensees","type":"hadith","ar":"إِنَّ اللَّهَ تَجَاوَزَ عَنْ أُمَّتِي مَا حَدَّثَتْ بِهِ أَنْفُسَهَا، مَا لَمْ تَعْمَلْ أَوْ تَتَكَلَّمْ","fr":"« Allah a pardonné à ma communauté ce que leurs âmes se suggèrent, tant qu'elles ne le font pas ou ne le disent pas. »","src":"Bukhârî 5269 · Muslim 127","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["choix","justice"],"title":"Les pensées qui traversent l’âme","note":"Les pensées involontaires ne sont pas dans ta zone de responsabilité ; tes actes et tes paroles, si.","link":"https://sunnah.com/bukhari:5269","narr":"Abû Hurayra"},{"id":"h-projet","type":"hadith","ar":"إِنَّ اللَّهَ كَتَبَ الْحَسَنَاتِ وَالسَّيِّئَاتِ، ثُمَّ بَيَّنَ ذَلِكَ فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ لَهُ عِنْدَهُ حَسَنَةً كَامِلَةً، فَإِنْ هُوَ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ لَهُ عِنْدَهُ عَشْرَ حَسَنَاتٍ إِلَى سَبْعِمِائَةِ ضِعْفٍ إِلَى أَضْعَافٍ كَثِيرَةٍ، وَمَنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ لَهُ عِنْدَهُ حَسَنَةً كَامِلَةً، فَإِنْ هُوَ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ لَهُ سَيِّئَةً وَاحِدَةً","fr":"« Allah a écrit les bonnes et les mauvaises actions, puis Il l'a expliqué : celui qui projette une bonne action et ne la fait pas, Allah la lui inscrit auprès de Lui comme une bonne action complète ; s'il la projette et la fait, Allah la lui inscrit comme dix bonnes actions, jusqu'à sept cents fois et bien plus encore. Et celui qui projette une mauvaise action et ne la fait pas, Allah la lui inscrit comme une bonne action complète ; s'il la projette et la fait, Allah la lui inscrit comme une seule mauvaise action. »","src":"Bukhârî 6491 · Muslim 131","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["choix","justice"],"title":"Le projet d’une bonne action","note":"","link":"https://sunnah.com/bukhari:6491","narr":"'Abdullâh ibn 'Abbâs"},{"id":"h-erreur","type":"hadith","ar":"إِنَّ اللَّهَ وَضَعَ عَنْ أُمَّتِي الْخَطَأَ وَالنِّسْيَانَ وَمَا اسْتُكْرِهُوا عَلَيْهِ","fr":"« Allah a dispensé ma communauté (de la faute commise par) erreur, par oubli, et de ce à quoi elle est contrainte. »","src":"Ibn Mâjah 2045","grade":"Sahîh (Darussalam) · hasan (an-Nawawî)","level":"sahih","themes":["choix","justice"],"title":"L'erreur, l'oubli et la contrainte","note":"","link":"https://sunnah.com/ibnmajah:2045","narr":"'Abdullâh ibn 'Abbâs"},{"id":"h-plume-levee","type":"hadith","ar":"رُفِعَ الْقَلَمُ عَنْ ثَلاَثَةٍ عَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ وَعَنِ الْمُبْتَلَى حَتَّى يَبْرَأَ وَعَنِ الصَّبِيِّ حَتَّى يَكْبَرَ","fr":"« La plume est levée pour trois : le dormeur jusqu'à ce qu'il se réveille, celui qui a perdu la raison jusqu'à ce qu'il guérisse, et l'enfant jusqu'à ce qu'il grandisse. »","src":"Abû Dâwûd 4398","grade":"Sahîh (al-Albânî)","level":"sahih","themes":["choix","justice"],"title":"La plume est levée pour trois","note":"La responsabilité suppose la raison, la connaissance et la capacité.","link":"https://sunnah.com/abudawud:4398","narr":"'Âïsha"},{"id":"h-refuse","type":"hadith","ar":"كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ، إِلاَّ مَنْ أَبَى. قَالُوا يَا رَسُولَ اللَّهِ وَمَنْ يَأْبَى قَالَ مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ، وَمَنْ عَصَانِي فَقَدْ أَبَى","fr":"« Toute ma communauté entrera au Paradis, sauf celui qui refuse. » On dit : « Ô Messager d'Allah, et qui refuse ? » Il dit : « Celui qui m'obéit entre au Paradis, et celui qui me désobéit a refusé. »","src":"Bukhârî 7280","grade":"Sahîh — Bukhârî","level":"sahih","themes":["choix"],"title":"Sauf celui qui refuse","note":"","link":"https://sunnah.com/bukhari:7280","narr":"Abû Hurayra"},{"id":"h-fitra","type":"hadith","ar":"كُلُّ مَوْلُودٍ يُولَدُ عَلَى الْفِطْرَةِ، فَأَبَوَاهُ يُهَوِّدَانِهِ أَوْ يُنَصِّرَانِهِ أَوْ يُمَجِّسَانِهِ","fr":"« Tout enfant naît selon la fitra (la nature originelle) ; ce sont ses parents qui en font un juif, un chrétien ou un mazdéen. »","src":"Bukhârî 1385 · Muslim 2658","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["khalq","hidaya"],"title":"Tout enfant naît selon la fitra","note":"","link":"https://sunnah.com/bukhari:1385","narr":"Abû Hurayra"},{"id":"h-enfants","type":"hadith","ar":"اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ","fr":"(Interrogé sur les enfants des polythéistes morts en bas âge, il dit :) « Allah sait mieux ce qu'ils auraient fait. »","src":"Bukhârî 1384 · Muslim 2659","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["ilm"],"title":"« Allah sait mieux ce qu'ils auraient fait »","note":"La science d'Allah embrasse même ce qui n'arrivera jamais : ce qui aurait été, si cela avait été.","link":"https://sunnah.com/bukhari:1384","narr":"Abû Hurayra"},{"id":"h-pecheurs","type":"hadith","ar":"وَالَّذِي نَفْسِي بِيَدِهِ لَوْ لَمْ تُذْنِبُوا لَذَهَبَ اللَّهُ بِكُمْ وَلَجَاءَ بِقَوْمٍ يُذْنِبُونَ فَيَسْتَغْفِرُونَ اللَّهَ فَيَغْفِرُ لَهُمْ","fr":"« Par Celui qui tient mon âme en Sa main, si vous ne péchiez pas, Allah vous ferait disparaître et ferait venir des gens qui pèchent, puis demandent pardon à Allah, et Il leur pardonne. »","src":"Muslim 2749","grade":"Sahîh — Muslim","level":"sahih","themes":["tawba","hikma"],"title":"Des gens qui pèchent et demandent pardon","note":"Ce hadith n'encourage pas le péché : il montre qu'Allah aime le repentir et qu'Il est le Pardonneur.","link":"https://sunnah.com/muslim:2749","narr":"Abû Hurayra"},{"id":"h-sharr","type":"hadith","ar":"وَالْخَيْرُ كُلُّهُ فِي يَدَيْكَ وَالشَّرُّ لَيْسَ إِلَيْكَ","fr":"(Dans l'invocation d'ouverture de la prière :) « … Le bien tout entier est entre Tes mains, et le mal ne Te revient pas. »","src":"Muslim 771","grade":"Sahîh — Muslim","level":"sahih","themes":["justice","hikma"],"title":"« Et le mal ne Te revient pas »","note":"Tout est créé par Allah, mais Son acte n'est jamais un mal : tout ce qu'Il fait est sagesse et justice. Le mal se trouve dans certaines choses créées, relativement à nous.","link":"https://sunnah.com/muslim:771","narr":"'Alî ibn Abî Tâlib"},{"id":"h-patience","type":"hadith","ar":"وَمَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ، وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ، وَمَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللَّهُ، وَمَا أُعْطِيَ أَحَدٌ عَطَاءً خَيْرًا وَأَوْسَعَ مِنَ الصَّبْرِ","fr":"« Celui qui cherche à rester digne (sans mendier), Allah le rend digne ; celui qui cherche à se suffire, Allah l'enrichit ; celui qui s'efforce d'être patient, Allah le rend patient. Et nul n'a reçu un don meilleur et plus vaste que la patience. »","src":"Bukhârî 1469","grade":"Sahîh — Bukhârî","level":"sahih","themes":["sabr","effort"],"title":"Celui qui s'efforce d'être patient","note":"La patience elle-même est un effort que tu entreprends, et qu'Allah complète.","link":"https://sunnah.com/bukhari:1469","narr":"Abû Sa'îd al-Khudrî"},{"id":"h-choc","type":"hadith","ar":"إِنَّمَا الصَّبْرُ عِنْدَ الصَّدْمَةِ الأُولَى","fr":"« La patience, c'est au premier choc. »","src":"Bukhârî 1283 · Muslim 926","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["sabr"],"title":"La patience, au premier choc","note":"Dit à une femme qui pleurait violemment sur une tombe et l'avait repoussé sans le reconnaître.","link":"https://sunnah.com/bukhari:1283","narr":"Anas ibn Mâlik"},{"id":"h-larmes","type":"hadith","ar":"إِنَّ الْعَيْنَ تَدْمَعُ، وَالْقَلْبَ يَحْزَنُ، وَلاَ نَقُولُ إِلاَّ مَا يَرْضَى رَبُّنَا، وَإِنَّا بِفِرَاقِكَ يَا إِبْرَاهِيمُ لَمَحْزُونُونَ","fr":"« L'œil verse des larmes, le cœur s'attriste, et nous ne disons que ce qui agrée notre Seigneur. Et nous sommes, par ta séparation, ô Ibrâhîm, attristés. »","src":"Bukhârî 1303 · Muslim 2315","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["sabr"],"title":"Les larmes du Prophète ﷺ","note":"Prononcé à la mort de son fils Ibrâhîm. Pleurer et être triste ne contredit pas la patience ; c'est la révolte en paroles et en gestes qui la contredit.","link":"https://sunnah.com/bukhari:1303","narr":"Anas ibn Mâlik"},{"id":"h-joues","type":"hadith","ar":"لَيْسَ مِنَّا مَنْ لَطَمَ الْخُدُودَ، وَشَقَّ الْجُيُوبَ، وَدَعَا بِدَعْوَى الْجَاهِلِيَّةِ","fr":"« N'est pas des nôtres celui qui se frappe les joues, déchire ses vêtements et lance les cris de la Jâhiliyya. »","src":"Bukhârî 1294 · Muslim 103","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["sabr"],"title":"Ce qui contredit la patience","note":"","link":"https://sunnah.com/bukhari:1294","narr":"'Abdullâh ibn Mas'ûd"},{"id":"h-ummsalama","type":"hadith","ar":"مَا مِنْ مُسْلِمٍ تُصِيبُهُ مُصِيبَةٌ فَيَقُولُ مَا أَمَرَهُ اللَّهُ إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا. إِلاَّ أَخْلَفَ اللَّهُ لَهُ خَيْرًا مِنْهَا","fr":"« Il n'est pas de musulman frappé par un malheur qui dise ce qu'Allah lui a ordonné : « Nous sommes à Allah et c'est vers Lui que nous retournerons ; ô Allah, récompense-moi dans mon malheur et donne-moi en échange mieux que cela », sans qu'Allah ne lui donne en échange mieux que cela. »","src":"Muslim 918","grade":"Sahîh — Muslim","level":"sahih","themes":["sabr","dua"],"title":"« Donne-moi mieux en échange »","note":"Umm Salama la dit à la mort de son mari Abû Salama, en se demandant qui pourrait être meilleur que lui. Allah lui donna pour époux le Messager d'Allah ﷺ.","link":"https://sunnah.com/muslim:918","narr":"Umm Salama"},{"id":"h-epine","type":"hadith","ar":"مَا يُصِيبُ الْمُسْلِمَ مِنْ نَصَبٍ وَلاَ وَصَبٍ وَلاَ هَمٍّ وَلاَ حُزْنٍ وَلاَ أَذًى وَلاَ غَمٍّ حَتَّى الشَّوْكَةِ يُشَاكُهَا، إِلاَّ كَفَّرَ اللَّهُ بِهَا مِنْ خَطَايَاهُ","fr":"« Aucune fatigue, aucune maladie, aucun souci, aucune tristesse, aucun mal, aucune angoisse n'atteint le musulman, pas même une épine qui le pique, sans qu'Allah n'efface par cela une partie de ses péchés. »","src":"Bukhârî 5641-5642 · Muslim 2572","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["sabr","hikma"],"title":"Même une épine","note":"","link":"https://sunnah.com/bukhari:5641","narr":"Abû Sa'îd · Abû Hurayra"},{"id":"h-bien","type":"hadith","ar":"مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُصِبْ مِنْهُ","fr":"« Celui à qui Allah veut du bien, Il le fait atteindre (par des épreuves). »","src":"Bukhârî 5645","grade":"Sahîh — Bukhârî","level":"sahih","themes":["sabr","hikma"],"title":"Celui à qui Allah veut du bien","note":"","link":"https://sunnah.com/bukhari:5645","narr":"Abû Hurayra"},{"id":"h-prophetes","type":"hadith","ar":"أَىُّ النَّاسِ أَشَدُّ بَلاَءً قَالَ الأَنْبِيَاءُ ثُمَّ الأَمْثَلُ فَالأَمْثَلُ فَيُبْتَلَى الرَّجُلُ عَلَى حَسَبِ دِينِهِ فَإِنْ كَانَ دِينُهُ صُلْبًا اشْتَدَّ بَلاَؤُهُ وَإِنْ كَانَ فِي دِينِهِ رِقَّةٌ ابْتُلِيَ عَلَى حَسَبِ دِينِهِ فَمَا يَبْرَحُ الْبَلاَءُ بِالْعَبْدِ حَتَّى يَتْرُكَهُ يَمْشِي عَلَى الأَرْضِ مَا عَلَيْهِ خَطِيئَةٌ","fr":"(Sa'd demanda : « Ô Messager d'Allah, quels sont les gens les plus durement éprouvés ? ») « Les prophètes, puis les meilleurs, puis les meilleurs après eux. L'homme est éprouvé selon sa religion : si sa religion est solide, son épreuve est plus forte ; s'il y a de la fragilité dans sa religion, il est éprouvé à la mesure de sa religion. L'épreuve ne quitte pas le serviteur jusqu'à le laisser marcher sur la terre sans aucun péché. »","src":"Tirmidhî 2398 · Ibn Mâjah 4023","grade":"Hasan sahîh (Tirmidhî)","level":"sahih","themes":["sabr","hikma"],"title":"Les plus éprouvés : les prophètes","note":"","link":"https://sunnah.com/tirmidhi:2398","narr":"Sa'd ibn Abî Waqqâs"},{"id":"h-ampleur","type":"hadith","ar":"إِنَّ عِظَمَ الْجَزَاءِ مَعَ عِظَمِ الْبَلاَءِ وَإِنَّ اللَّهَ إِذَا أَحَبَّ قَوْمًا ابْتَلاَهُمْ فَمَنْ رَضِيَ فَلَهُ الرِّضَا وَمَنْ سَخِطَ فَلَهُ السَّخَطُ","fr":"« L'ampleur de la récompense va avec l'ampleur de l'épreuve. Quand Allah aime des gens, Il les éprouve : à celui qui est satisfait, la satisfaction (d'Allah) ; à celui qui s'irrite, l'irritation. »","src":"Tirmidhî 2396 · Ibn Mâjah 4031","grade":"Hasan","level":"hasan","themes":["sabr"],"title":"À qui est satisfait, la satisfaction","note":"","link":"https://sunnah.com/tirmidhi:2396","narr":"Anas ibn Mâlik"},{"id":"h-mort","type":"hadith","ar":"لاَ يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ مِنْ ضُرٍّ أَصَابَهُ، فَإِنْ كَانَ لاَ بُدَّ فَاعِلاً فَلْيَقُلِ اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي","fr":"« Que nul d'entre vous ne souhaite la mort à cause d'un mal qui l'a atteint. S'il doit absolument le faire, qu'il dise : « Ô Allah, fais-moi vivre tant que la vie est un bien pour moi, et fais-moi mourir quand la mort est un bien pour moi. » »","src":"Bukhârî 5671 · Muslim 2680","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["sabr","vie","dua"],"title":"Ne pas souhaiter la mort","note":"","link":"https://sunnah.com/bukhari:5671","narr":"Anas ibn Mâlik"},{"id":"h-zann","type":"hadith","ar":"أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا ذَكَرَنِي","fr":"(Allah dit :) « Je suis conforme à l'opinion que Mon serviteur a de Moi, et Je suis avec lui quand il se souvient de Moi. »","src":"Bukhârî 7405 · Muslim 2675","grade":"Sahîh — Bukhârî & Muslim","level":"sahih","themes":["tawakkul","dua"],"title":"« Je suis conforme à l'opinion de Mon serviteur »","note":"","link":"https://sunnah.com/bukhari:7405","narr":"Abû Hurayra"},{"id":"h-hasbuna","type":"hadith","ar":"﴿حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ﴾ قَالَهَا إِبْرَاهِيمُ عَلَيْهِ السَّلاَمُ حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ صلى الله عليه وسلم حِينَ قَالُوا ﴿إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ﴾","fr":"« Allah nous suffit, et quel excellent Garant ! » : Ibrâhîm la dit quand il fut jeté dans le feu, et Muhammad ﷺ la dit quand on leur dit : « Les gens se sont rassemblés contre vous, craignez-les » (3:173).","src":"Bukhârî 4563 (parole d’Ibn ‘Abbâs)","grade":"Sahîh — Bukhârî","level":"sahih","themes":["tawakkul"],"title":"« Allah nous suffit » : Ibrâhîm et Muhammad ﷺ","note":"","link":"https://sunnah.com/bukhari:4563","narr":"'Abdullâh ibn 'Abbâs"},{"id":"h-devin","type":"hadith","ar":"مَنْ أَتَى عَرَّافًا فَسَأَلَهُ عَنْ شَىْءٍ لَمْ تُقْبَلْ لَهُ صَلاَةٌ أَرْبَعِينَ لَيْلَةً","fr":"« Celui qui va voir un devin et l'interroge sur quelque chose, sa prière ne sera pas acceptée pendant quarante nuits. »","src":"Muslim 2230","grade":"Sahîh — Muslim","level":"sahih","themes":["ghayb"],"title":"Chercher à connaître son destin","note":"Horoscopes, voyance, tirage de cartes : chercher à lire le destin caché est interdit.","link":"https://sunnah.com/muslim:2230","narr":"Une épouse du Prophète ﷺ"},{"id":"h-tiyara","type":"hadith","ar":"الطِّيَرَةُ شِرْكٌ","fr":"« La tiyara (tirer des présages) est une forme d'association (shirk). »","src":"Abû Dâwûd 3910","grade":"Sahîh (al-Albânî)","level":"sahih","themes":["ghayb","tawakkul"],"title":"Les présages","note":"Croire qu'un signe (un oiseau, un chiffre, un jour) décide de ton sort revient à attribuer à la création ce qui n'appartient qu'à Allah.","link":"https://sunnah.com/abudawud:3910","narr":"'Abdullâh ibn Mas'ûd"},{"id":"h-dispute","type":"hadith","ar":"وَنَحْنُ نَتَنَازَعُ فِي الْقَدَرِ فَغَضِبَ حَتَّى احْمَرَّ وَجْهُهُ حَتَّى كَأَنَّمَا فُقِئَ فِي وَجْنَتَيْهِ الرُّمَّانُ فَقَالَ أَبِهَذَا أُمِرْتُمْ أَمْ بِهَذَا أُرْسِلْتُ إِلَيْكُمْ إِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ حِينَ تَنَازَعُوا فِي هَذَا الأَمْرِ عَزَمْتُ عَلَيْكُمْ أَلاَّ تَتَنَازَعُوا فِيهِ","fr":"Le Messager d'Allah ﷺ sortit vers nous alors que nous nous disputions au sujet du destin. Il se mit en colère au point que son visage rougit, comme si des grains de grenade avaient éclaté sur ses joues, et dit : « Est-ce cela qu'on vous a ordonné, ou est-ce pour cela que j'ai été envoyé vers vous ? Ceux qui vous ont précédés n'ont péri que lorsqu'ils se sont disputés sur cette question. Je vous adjure de ne pas vous disputer à son sujet. »","src":"Tirmidhî 2133","grade":"Hasan (al-Albânî) · gharîb (Tirmidhî)","level":"hasan","themes":["excuse"],"title":"Ne pas se disputer sur le destin","note":"Comprendre le destin pour mieux agir est une chose ; disputer de son secret en est une autre.","link":"https://sunnah.com/tirmidhi:2133","narr":"Abû Hurayra"},{"id":"s-tahawi","title":"Le secret du destin","ar":"وَأَصْلُ القَدَرِ سِرُّ اللهِ تَعَالَى فِي خَلْقِهِ، لَمْ يَطَّلِعْ عَلَى ذَلِكَ مَلَكٌ مُقَرَّبٌ، وَلَا نَبِيٌّ مُرْسَلٌ","fr":"Le fond du destin est le secret d'Allah dans Sa création : ni ange rapproché ni prophète envoyé n'en a été informé.","src":"Abû Ja'far at-Tahâwî (m. 321 H), al-'Aqîda at-Tahâwiyya","themes":["ilm","hikma"],"type":"savant","grade":"Parole savante","level":"savant","note":"","link":""},{"id":"s-qayyim-cadre","title":"Avant et après le décret","ar":"فَالمَقْدُورُ يَكْتَنِفُهُ أَمْرَانِ: التَّوَكُّلُ قَبْلَهُ، وَالرِّضَا بَعْدَهُ","fr":"Ce qui est décrété est encadré par deux choses : la confiance en Allah avant lui, et le contentement après lui.","src":"Ibn al-Qayyim (m. 751 H), Zâd al-Ma'âd, au sujet de l'istikhâra","themes":["tawakkul","sabr"],"type":"savant","grade":"Parole savante","level":"savant","note":"","link":""},{"id":"s-qayyim-trois","title":"Les trois signes du bonheur","ar":"إِذَا أُعْطِيَ شَكَرَ، وَإِذَا ابْتُلِيَ صَبَرَ، وَإِذَا أَذْنَبَ اسْتَغْفَرَ","fr":"Quand on lui donne, il remercie ; quand il est éprouvé, il patiente ; quand il pèche, il demande pardon. Ces trois choses sont le signe du bonheur du serviteur.","src":"Ibn al-Qayyim, al-Wâbil as-Sayyib (introduction)","themes":["shukr","sabr","tawba"],"type":"savant","grade":"Parole savante","level":"savant","note":"","link":""},{"id":"s-taymiyya-causes","title":"Les causes : ni s’y fier, ni les nier","ar":"الالْتِفَاتُ إِلَى الأَسْبَابِ شِرْكٌ فِي التَّوْحِيدِ، وَمَحْوُ الأَسْبَابِ أَنْ تَكُونَ أَسْبَابًا نَقْصٌ فِي العَقْلِ، وَالإِعْرَاضُ عَنِ الأَسْبَابِ بِالكُلِّيَّةِ قَدْحٌ فِي الشَّرْعِ","fr":"S'appuyer du cœur sur les causes est une atteinte au tawhîd ; nier que les causes soient des causes est un défaut de raison ; et délaisser totalement les causes est une atteinte à la Loi révélée.","src":"Ibn Taymiyya (m. 728 H), Majmû' al-Fatâwâ","themes":["effort","tawakkul"],"type":"savant","grade":"Parole savante","level":"savant","note":"","link":""},{"id":"s-regle","title":"Les malheurs, pas les fautes","ar":"يُحْتَجُّ بِالقَدَرِ عَلَى المَصَائِبِ، لَا عَلَى المَعَايِبِ","fr":"On invoque le destin face aux malheurs, pas pour justifier les fautes.","src":"Règle tirée du hadith d'Adam et Moïse, expliquée par Ibn Taymiyya et Ibn al-Qayyim","themes":["excuse"],"type":"savant","grade":"Parole savante","level":"savant","note":"","link":""},{"id":"s-maratib","title":"Les quatre degrés du destin","ar":"العِلْمُ، وَالكِتَابَةُ، وَالمَشِيئَةُ، وَالخَلْقُ","fr":"La science, l'écriture, la volonté et la création : quiconque croit à ces quatre degrés croit au destin tel que l'ont compris les Compagnons.","src":"Synthèse d'Ibn al-Qayyim, Shifâ' al-'Alîl","themes":["ilm","kitaba","mashia","khalq"],"type":"savant","grade":"Parole savante","level":"savant","note":"","link":""}]};
